INSERT INTO `price` VALUES (9,'Báo giá hộp giấy tổng quát',100,'[{\"title\":\"Tham Số Chung\",\"type\":\"title_group\",\"position\":\"left\",\"show\":true},{\"title\":\"Số Lượng\",\"type\":\"input_number\",\"input\":{\"variable\":\"so_luong\",\"min_value\":\"500\",\"max_value\":\"100000\",\"require\":true,\"default_value\":1000},\"position\":\"left\",\"show\":true},{\"title\":\"Ngang-Dài(L:cm)\",\"type\":\"input_number\",\"input\":{\"variable\":\"dai\",\"min_value\":\"2\",\"max_value\":\"40\",\"require\":true,\"default_value\":10},\"position\":\"left\",\"show\":true},{\"title\":\"Cao(H:cm)\",\"type\":\"input_number\",\"input\":{\"variable\":\"cao\",\"min_value\":\"2\",\"max_value\":\"30\",\"require\":true,\"default_value\":10},\"position\":\"left\",\"show\":true},{\"title\":\"Rộng-Hông(W:cm)\",\"type\":\"input_number\",\"input\":{\"variable\":\"rong\",\"min_value\":\"2\",\"max_value\":\"40\",\"require\":true,\"default_value\":10},\"position\":\"left\",\"show\":true},{\"title\":\"Kiểu Hộp\",\"type\":\"select\",\"select\":{\"variable\":\"kieu_hop\",\"options\":[{\"key\":\"Hộp nắp mở 2 đáy\",\"value\":\"1\"},{\"key\":\"Hộp nắp mở đáy gài\",\"value\":\"2\"},{\"key\":\"Hộp nắp mở 2 đáy có móc treo\",\"value\":\"3\"},{\"key\":\"Hộp nắp mở 2 đáy khóa 2 đầu\",\"value\":\"4\"},{\"key\":\"Hộp nắp mở đáy gài khóa 1 đầu\",\"value\":\"5\"},{\"key\":\"Hộp nắp mở 2 đáy khóa 1 đầu\",\"value\":\"6\"},{\"key\":\"Hộp quai xách (đáy gài)\",\"value\":\"7\"},{\"key\":\"Hộp nắp mở cạnh Piza\",\"value\":\"8\"},{\"key\":\"Hộp nắp mở (đựng giày)\",\"value\":\"9\"}],\"require\":true,\"default_value\":\"1\"},\"position\":\"left\",\"show\":true},{\"title\":\"Loại Giấy\",\"type\":\"select\",\"select\":{\"variable\":\"loai_giay\",\"options\":[{\"key\":\"Couches bóng\",\"value\":\"C\"},{\"key\":\"Briston (C Pindo)\",\"value\":\"B\"},{\"key\":\"Ivory\",\"value\":\"I\"},{\"key\":\"Duplex\",\"value\":\"D\"},{\"key\":\"Kraft\",\"value\":\"K\"}],\"require\":true,\"default_value\":\"I\"},\"position\":\"