INSERT INTO `price_formulas` VALUES (4,100,'Lấy Tai Dán','lay_tai_dan','function lay_tai_dan(rong) {\r\n    if (rong <= 1) return 0.7;\r\n    if (rong>1&& rong <= 7) return 1.5;\r\n    if (rong>7&&rong <= 20) return 2;\r\n    if (rong>20 &&rong <= 35) return 2.5;\r\n    return 1.5;\r\n}','','',9,'1616243922','1616297479'),(5,95,'Lấy Khóa Gài','lay_khoa_gai','function lay_khoa_gai(rong) {\r\n    if (rong &lt;= 1) return 1.5;\r\n    if (rong>1&&rong &lt;= 7) return 2;\r\n    if (rong>7&&rong &lt;= 20) return 2.5;\r\n    if (rong>20&&rong &lt;= 35) return 2.5;\r\n    return 2;\r\n}','','',9,'1616243952','1616243952'),(6,90,'Tính Khổ Trải Dài','tinh_kho_trai_ngang(dai, rong, kieu_hop)','function tinh_kho_trai_ngang(dai, rong, kieu_hop) {\r\n\r\n  var kho_trai_ngang =0;\r\n    \r\n    \r\n    if (kieu_hop == 1 || kieu_hop== 2) kho_trai_ngang= (dai + rong) * 2 + 1.5;\r\n\r\n    if (kieu_hop == 3) kho_trai_ngang=(dai + rong) * 2 + 1.5;\r\n\r\n     if (kieu_hop == 4) kho_trai_ngang=(dai + rong) * 2 + 1.5;\r\n     \r\n    if (kieu_hop == 5)kho_trai_ngang=(dai + rong) * 2 + 1.5;\r\n    \r\n    //Hộp nắp mở 2 đáy khóa 1 đầu\r\n    if (kieu_hop == 6) kho_trai_ngang= (dai + rong) * 2 + 1.5;\r\n    \r\n    if (kieu_hop == 7)  kho_trai_ngang= (dai + rong) * 2 + 1.5;\r\n    \r\n    //Dài+(Rộng+0.2)x4+1.6 Hộp nắp mở cạnh nắp gài chắc\r\n    if (kieu_hop == 8) kho_trai_ngang= dai +(rong+0.2)*4 +1.6;\r\n    \r\n    //Hộp nắp mở cạnh piza Dài+Rộngx4+0.4\r\n\r\n     if (kieu_hop == 9) kho_trai_ngang= dai +rong*4 +0.4;\r\n     \r\n     return kho_trai_ngang+0.2;\r\n}','','',36,'1616243991','1617506467'),(7,85,'Tính Khổ Trải Cao','tinh_kho_trai_cao(cao, rong, kieu_hop)','function tinh_kho_trai_cao(cao, rong, kieu_hop) {\r\n    \r\n  var kho_trai_cao =0;\r\n  //Hộp nắp mở 2 đáy\r\n   if (kieu_hop==1) kho_trai_cao= (cao+2*(rong+1.7));// cao + rong*2+2*2.17\r\n   \r\n   //Hộp nắp mở đáy gài \r\n    if (kieu_hop==2) kho_trai_cao= cao+rong+1.5+ rong/2+1.5 ;\r\n    \r\n    //Hộp nắp mở 2 đáy có móc treo\r\n   if (kieu_hop==3) kho_trai_cao= cao+rong+1.5+8+1.5;\r\n   //Hộp nắp mở 2 đáy khóa 2 đầu\r\n   if (kieu_hop==4) kho_trai_cao= (cao+2*(rong+1.5));\r\n   //Hộp nắp mở đáy gài khóa 1 đầu\r\n   if (kieu_hop==5) kho_trai_cao=  cao+rong+1.5+ rong/2+1.5 ;\r\n   //Hộp nắp mở 2 đáy khóa 1 đầu\r\n     if (kieu_hop==6) kho_trai_cao= (cao+2*(rong+1.5));// cao + rong*2+2*2.17\r\n      //Hộp quai xách (đáy gài) -Cao+Rộng/2+2.5+Rộng/2+8\r\n\r\n     if (kieu_hop==7) kho_trai_cao=rong/2+ cao+ 2 + rong/2 + 7;\r\n     //Hộp nắp mở cạnh nắp gài chắc -(Cao+Rộng)x2+(Rộng+0.2)\r\n  if (kieu_hop==8) kho_trai_cao=(cao+rong)*2+rong+0.2;\r\n  //Hộp nắp mở cạnh piza-(Cao+Rộng)x2+3\r\n\r\n if (kieu_hop==9) kho_trai_cao=(cao+rong)*2+3;\r\n   \r\n   return kho_trai_cao+0.2;\r\n}','','',36,'1616244031','1617788968'),(8,80,'lay_gia_ram_giay_65_86(loai_giay,dinh_luong)','lay_gia_ram_giay_65_86(loai_giay,dinh_luong)','function lay_gia_ram_giay_65_86(loai_giay,dinh_luong){\r\n    \r\n    var gia_ram_giay=0;\r\n     // định lượng 200 g/m2\r\n      if(dinh_luong==100 )\r\n    {\r\n               // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <65_86_Couche_100>;          \r\n             if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_100>;\r\n           \r\n    }\r\n      if(dinh_luong==120 )\r\n    {\r\n            \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <65_86_Couche_120>;          \r\n             if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_120>;\r\n    }\r\n      if(dinh_luong==150 )\r\n    {\r\n            \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <65_86_Couche_150>;  \r\n            //Kraft\r\n            if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_150>;\r\n             \r\n    }\r\n    if(dinh_luong==180)\r\n    {\r\n        //Kraft\r\n            if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_180>;\r\n    }\r\n    //\r\n     if(dinh_luong==200 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<65_86_Ivory_200>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <65_86_Couche_200>;          \r\n             \r\n             // Briston (C Pindo)\r\n           if(loai_giay==\"B\")   gia_ram_giay=  <65_86_Briston_200>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <65_86_Duplex_200>;\r\n             if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_200>;\r\n         \r\n    }\r\n     // định lượng 250 g/m2\r\n     if(dinh_luong==250 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<65_86_Ivory_250>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <65_86_Couche_250>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_ram_giay=  <65_86_Briston_250>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <65_86_Duplex_250>;\r\n            if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_250>;\r\n         \r\n    }\r\n    // định lượng 300 g/m2\r\n    if(dinh_luong==300 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<65_86_Ivory_300>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <65_86_Couche_300>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_ram_giay= <65_86_Briston_300>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <65_86_Duplex_300>;\r\n               // Kraft\r\n            if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_300>;\r\n         \r\n    }\r\n    \r\n   // định lượng 350 g/m2\r\n    if(dinh_luong==350 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<65_86_Ivory_350>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <65_86_Couche_350>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_ram_giay= <65_86_Briston_350>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <65_86_Duplex_350>;\r\n             if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_350>;\r\n         \r\n    }\r\n     // định lượng 400 g/m2\r\n    if(dinh_luong==400||dinh_luong==450 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<65_86_Ivory_400>;\r\n          \r\n             // Couches bóng -\r\n            if(loai_giay==\"C\")  gia_ram_giay= <65_86_Couche_400>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_ram_giay= <65_86_Briston_400>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <65_86_Duplex_400>;\r\n              if(loai_giay==\"K\") gia_ram_giay= <65_86_Kraft_400>;\r\n         \r\n    }\r\n  return gia_ram_giay;\r\n}','[\"680\",\"732\",\"715\",\"664\",\"733\",\"716\",\"688\",\"879\",\"665\",\"687\",\"880\",\"714\",\"881\",\"686\",\"713\",\"883\",\"711\",\"886\",\"885\",\"684\",\"693\",\"681\",\"683\",\"682\",\"966\",\"970\",\"971\",\"972\",\"968\",\"967\",\"969\",\"973\",\"965\",\"997\"]','',34,'1616244100','1677386253'),(9,75,'Láy giá ram giấy khổ 79x109','lay_gia_ram_giay_79_109(loai_giay,dinh_luong)','function lay_gia_ram_giay_79_109(loai_giay,dinh_luong){\r\n    \r\n    var gia_ram_giay=0;\r\n     // định lượng 200 g/m2\r\n       // định lượng 200 g/m2\r\n      if(dinh_luong==100 )\r\n    {\r\n               // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_100>;          \r\n            if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_100>; \r\n           \r\n    }\r\n      if(dinh_luong==120 )\r\n    {\r\n            \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_120>; \r\n             if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_120>;\r\n             \r\n    }\r\n      if(dinh_luong==150 )\r\n    {\r\n            \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_150>;   \r\n            if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_150>;\r\n             \r\n    }\r\n      if(dinh_luong==180 )\r\n    {\r\n            \r\n             // Couches bóng\r\n            //if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_150>;   \r\n            if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_180>;\r\n             \r\n    }\r\n     if(dinh_luong==200 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<79_109_Ivory_200>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_200>;          \r\n             \r\n             // Briston (C Pindo)\r\n           if(loai_giay==\"B\")   gia_ram_giay=  <79_109_Briston_200>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <79_109_Duplex_200>;\r\n            if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_200>;\r\n         \r\n    }\r\n     // định lượng 250 g/m2\r\n     if(dinh_luong==250 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<79_109_Ivory_250>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_250>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_ram_giay=  <79_109_Briston_250>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <79_109_Duplex_250>;\r\n             if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_250>;\r\n         \r\n    }\r\n    // định lượng 300 g/m2\r\n    if(dinh_luong==300 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<79_109_Ivory_300>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_300>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_ram_giay= <79_109_Briston_300>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <79_109_Duplex_300>;\r\n           if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_300>;\r\n    }\r\n    \r\n   // định lượng 350 g/m2\r\n    if(dinh_luong==350 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<79_109_Ivory_350>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_350>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_ram_giay= <79_109_Briston_350>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <79_109_Duplex_350>;\r\n           if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_350>;\r\n    }\r\n     // định lượng 400 g/m2\r\n    if(dinh_luong==400||dinh_luong==450)\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_ram_giay =<79_109_Ivory_400>;\r\n          \r\n             // Couches bóng -\r\n            if(loai_giay==\"C\")  gia_ram_giay= <79_109_Couche_400>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_ram_giay= <79_109_Briston_400>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_ram_giay= <79_109_Duplex_400>;\r\n           if(loai_giay==\"K\") gia_ram_giay= <79_109_Kraft_400>;\r\n    }\r\n  return gia_ram_giay;\r\n}','[\"887\",\"694\",\"888\",\"718\",\"670\",\"696\",\"720\",\"890\",\"671\",\"697\",\"891\",\"721\",\"889\",\"698\",\"734\",\"722\",\"673\",\"723\",\"735\",\"892\",\"691\",\"692\",\"693\",\"974\",\"975\",\"966\",\"976\",\"977\",\"978\",\"765\",\"764\",\"998\"]','',34,'1616244149','1677386369'),(10,70,'Hàm tìm min của 2 số','MinTwoNum( a,  b)','function MinTwoNum( a,  b){\r\n    return (a &lt; b ? a : b);\r\n    \r\n}','','',9,'1616244184','1616244192'),(11,65,'Hàm tìm max của 2 số','MaxTwoNum( a,  b)','// Hàm tìm max của 2 số\r\nfunction MaxTwoNum( a,  b){\r\n    return (a > b ? a : b);\r\n}','','',9,'1616244257','1616244257'),(12,60,'Tìm min 3 số','MinThreeNum( a,  b,  c)','function MinThreeNum( a,  b,  c){\r\n    return MinTwoNum(a, MinTwoNum(b, c));\r\n}','','[\"10\"]',9,'1616244285','1616332651'),(13,55,'Hàm tìm max 3 số','MaxThreeNum( a,  b,  c)','function MaxThreeNum( a,  b,  c){\r\n    var m = MaxTwoNum(a, b);\r\n    var ans = MaxTwoNum(m, c);\r\n    return ans;\r\n}','','[\"11\"]',9,'1616244314','1616334016'),(14,55,'Lấy Chiều Dài Khổ Giấy  In','lay_chieu_dai_giay(kho_giay)','function lay_chieu_dai_giay(kho_giay)\r\n{\r\n    var d=86;\r\n    try {\r\n       d=kho_giay.split(\'x\')[1];\r\n    }\r\n    catch(err) \r\n    {\r\n        //message[removed] = \"Input is \" + err;\r\n        d=86;\r\n    }\r\n   return parseFloat(d);\r\n}','','',9,'1616244345','1618021023'),(15,50,'Lấy Chiều Rộng Khổ Giấy In','lay_chieu_rong_giay(kho_giay)','function lay_chieu_rong_giay(kho_giay)\r\n{\r\n    var r=65;\r\n    try {\r\n       r=kho_giay.split(\'x\')[0]; //return parseInt(kho_giay.split(\'x\')[0]);\r\n    }\r\n    catch(err) \r\n    {\r\n        return 0;\r\n    }\r\n   return parseFloat(r);\r\n}','','',9,'1616244539','1618020999'),(16,45,'Lấy số tờ giấy bù hao','lay_sl_to_bu_hao(so_con_tren_to)','function lay_sl_to_bu_hao(so_con_tren_to) {\r\n    if (so_con_tren_to==0)\r\n    return 0;\r\n    if (so_con_tren_to == 1) \r\n        return <so_to_bu_hao_toi_da> ;\r\n    return Math.ceil(<so_to_bu_hao_toi_da>/so_con_tren_to);\r\n}','[\"663\"]','',9,'1616244574','1641185098'),(17,40,'Lấy số sản phẩm trên tờ','lay_so_sp_tren_to(dai,rong,cao, kieu_hop,rong_kho_giay,dai_kho_giay)','function lay_so_sp_tren_to(dai,rong,cao, kieu_hop,rong_kho_giay,dai_kho_giay){\r\n      \r\n     var kho_trai_cao=0;//=tinh_kho_trai_cao(cao, rong, kieu_hop);\r\n     var kho_trai_ngang=0;//=tinh_kho_trai_ngang(dai,rong, kieu_hop);\r\n     \r\n       // nếu là hộp giấy\r\n         kho_trai_cao=tinh_kho_trai_cao(cao, rong, kieu_hop);\r\n          kho_trai_ngang=tinh_kho_trai_ngang(dai,rong, kieu_hop);\r\n     // nếu là túi giấy\r\n     if(kieu_hop==30||kieu_hop==31||kieu_hop==32||kieu_hop==33)\r\n     {\r\n          kho_trai_cao=tinh_kho_trai_cao_tg(cao, rong,kieu_hop);\r\n          kho_trai_ngang=tinh_kho_trai_ngang_tg(dai,rong,kieu_hop);\r\n     }\r\n     if(kieu_hop==20||kieu_hop==21||kieu_hop==22)\r\n     {\r\n          kho_trai_cao=tinh_kho_trai_cao_tg(cao, rong);\r\n          kho_trai_ngang=tinh_kho_trai_ngang_tg(dai,rong);\r\n     }\r\n     \r\n     \r\n     var kho_trai_cao_2_sp =kho_trai_cao*2;\r\n     var kho_trai_cao_3_sp =kho_trai_cao*3;\r\n     //return kho_trai_cao;\r\n    \r\n     // kiểu ghép hộp ngang\r\n     var tong_sp_ghep_ngang=0;\r\n     var so_sp_xep_ngang_ghep_ngang=0;\r\n     var so_sp_xep_doc_ghep_ngang=0;\r\n     tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n     \r\n      // kiểu ghép hộp dọc\r\n     var tong_sp_ghep_doc=0;\r\n     var so_sp_xep_ngang_ghep_doc=0;\r\n     var so_sp_xep_doc_ghep_doc=0;\r\n     tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n     // số lượng sản trên tờ \r\n       \r\n     // nếu kiểu hộp rơi vào Hộp dán hông đáy xếp, 1 khóa gài hoặc Hộp dán hông 2 khóa cài (RTE)\r\n     \r\n     // kiểu ghép hộp ngang 2 sp\r\n     var tong_sp_ghep_ngang_2p=0;\r\n     var so_sp_xep_ngang_ghep_ngang_2p=0;\r\n     var so_sp_xep_doc_ghep_ngang_2p=0;\r\n     tong_sp_ghep_ngang_2p=so_sp_xep_ngang_ghep_ngang_2p*so_sp_xep_doc_ghep_ngang_2p;\r\n     \r\n      // kiểu ghép hộp dọc 2p\r\n     var tong_sp_ghep_doc_2p=0;\r\n     var so_sp_xep_ngang_ghep_doc_2p=0;\r\n     var so_sp_xep_doc_ghep_doc_2p=0;\r\n     tong_sp_ghep_doc_2p=so_sp_xep_ngang_ghep_doc_2p*so_sp_xep_doc_ghep_doc_2p;\r\n     // số lượng sản trên tờ \r\n    \r\n     var max_sp_ghep =0;\r\n     if(kieu_hop==1||kieu_hop ==2||kieu_hop ==3)\r\n     {\r\n        \r\n           kho_trai_cao_2_sp=kho_trai_cao_2_sp-(rong + 2);\r\n          \r\n          // trường hợp ghép ngang  an gian giấy\r\n     \r\n          so_sp_xep_ngang_2p=2*Math.floor(dai_kho_giay/kho_trai_cao_2_sp);\r\n         \r\n          so_sp_xep_doc_ghep_ngang_2p=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          tong_sp_ghep_ngang_2p=so_sp_xep_ngang_2p*so_sp_xep_doc_ghep_ngang_2p;\r\n          \r\n        // trường hợp ghép dọc  an giấy\r\n            so_sp_xep_ngang_ghep_doc_2p=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n            so_sp_xep_doc_ghep_doc_2p=2*Math.floor(rong_kho_giay/kho_trai_cao_2_sp);\r\n            tong_sp_ghep_doc_2p=so_sp_xep_ngang_ghep_doc_2p*so_sp_xep_doc_ghep_doc_2p;\r\n       \r\n     }\r\n     // trường hợp 4,5 phải cộng 1.2cm\r\n     \r\n     if(kieu_hop ==4||kieu_hop ==5||kieu_hop ==6)\r\n     {\r\n        \r\n           kho_trai_cao_2_sp=kho_trai_cao_2_sp-(rong + 2)+1.2;\r\n          \r\n          // trường hợp ghép ngang  an gian giấy\r\n     \r\n          so_sp_xep_ngang_2p=2*Math.floor(dai_kho_giay/kho_trai_cao_2_sp);\r\n         \r\n          so_sp_xep_doc_ghep_ngang_2p=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          tong_sp_ghep_ngang_2p=so_sp_xep_ngang_2p*so_sp_xep_doc_ghep_ngang_2p;\r\n          \r\n        // trường hợp ghép dọc  an giấy\r\n            so_sp_xep_ngang_ghep_doc_2p=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n            so_sp_xep_doc_ghep_doc_2p=2*Math.floor(rong_kho_giay/kho_trai_cao_2_sp);\r\n            tong_sp_ghep_doc_2p=so_sp_xep_ngang_ghep_doc_2p*so_sp_xep_doc_ghep_doc_2p;\r\n       \r\n     }\r\n     var tong_sp_ghep_3=0;\r\n     \r\n    //Hộp nắp mở 2 đáy an gian giấy ghép 3\r\n     if (kieu_hop==1)\r\n     {  \r\n         // return kho_trai_cao_3_sp;\r\n         kho_trai_cao_3_sp=kho_trai_cao_3_sp-2*(rong + 2);\r\n          //return kho_trai_cao_3_sp;\r\n        // trường hợp ghép ngang  an gian giấy\r\n         \r\n         var so_sp_xep_ngang_3p=3*Math.floor(dai_kho_giay/kho_trai_cao_3_sp);\r\n           //return so_sp_xep_ngang_3p;\r\n         var so_sp_xep_doc_ghep_ngang_3p=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n              //return so_sp_xep_doc_ghep_ngang_3p;\r\n          var tong_sp_ghep_ngang_3p=so_sp_xep_ngang_3p*so_sp_xep_doc_ghep_ngang_3p;\r\n          \r\n        // trường hợp ghép dọc an giấy\r\n      \r\n          var  so_sp_xep_ngang_ghep_doc_3p=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n          // return so_sp_xep_ngang_ghep_doc_3p;\r\n          var  so_sp_xep_doc_ghep_doc_3p=3*Math.floor(rong_kho_giay/kho_trai_cao_3_sp);\r\n             //return so_sp_xep_doc_ghep_doc_3p;\r\n             //return so_sp_xep_doc_ghep_doc_3p;\r\n           var tong_sp_ghep_doc_3p=so_sp_xep_doc_ghep_doc_3p*so_sp_xep_ngang_ghep_doc_3p;\r\n           \r\n           tong_sp_ghep_3=MaxTwoNum(tong_sp_ghep_ngang_3p,tong_sp_ghep_doc_3p);\r\n     }\r\n     //Hộp nắp mở 2 đáy khóa 2 đầu an gian giấy ghép 3 phải cộng 1.2\r\n     if (kieu_hop==4||kieu_hop==6)\r\n     {  \r\n         // return kho_trai_cao_3_sp;\r\n         kho_trai_cao_3_sp=kho_trai_cao_3_sp-2*(rong + 2+1.2);\r\n          //return kho_trai_cao_3_sp;\r\n        // trường hợp ghép ngang  an gian giấy\r\n         \r\n          so_sp_xep_ngang_3p=3*Math.floor(dai_kho_giay/kho_trai_cao_3_sp);\r\n           //return so_sp_xep_ngang_3p;\r\n          so_sp_xep_doc_ghep_ngang_3p=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n              //return so_sp_xep_doc_ghep_ngang_3p;\r\n           tong_sp_ghep_ngang_3p=so_sp_xep_ngang_3p*so_sp_xep_doc_ghep_ngang_3p;\r\n          \r\n        // trường hợp ghép dọc an giấy\r\n      \r\n            so_sp_xep_ngang_ghep_doc_3p=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n          // return so_sp_xep_ngang_ghep_doc_3p;\r\n            so_sp_xep_doc_ghep_doc_3p=3*Math.floor(rong_kho_giay/kho_trai_cao_3_sp);\r\n             //return so_sp_xep_doc_ghep_doc_3p;\r\n             //return so_sp_xep_doc_ghep_doc_3p;\r\n            tong_sp_ghep_doc_3p=so_sp_xep_doc_ghep_doc_3p*so_sp_xep_ngang_ghep_doc_3p;\r\n           \r\n           tong_sp_ghep_3=MaxTwoNum(tong_sp_ghep_ngang_3p,tong_sp_ghep_doc_3p);\r\n     }\r\n     \r\n       // trường hợp ghép ngang không an gian giấy\r\n \r\n          so_sp_xep_ngang_ghep_ngang=Math.floor(dai_kho_giay/kho_trai_cao);\r\n         // return so_sp_xep_ngang;  \r\n          so_sp_xep_doc_ghep_ngang=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          \r\n          tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n          \r\n       // trường hợp ghép dọc\r\n   \r\n        so_sp_xep_ngang_ghep_doc=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n         \r\n        so_sp_xep_doc_ghep_doc=Math.floor(rong_kho_giay/kho_trai_cao);\r\n        \r\n        tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n        \r\n        var tong=0;\r\n        tong= MaxThreeNum( MaxTwoNum(tong_sp_ghep_ngang_2p,tong_sp_ghep_doc_2p),tong_sp_ghep_3,MaxTwoNum(tong_sp_ghep_ngang,tong_sp_ghep_doc));\r\nif(tong==0) tong =1;\r\nreturn tong;\r\n      //return MaxThreeNum( MaxTwoNum(tong_sp_ghep_ngang_2p,tong_sp_ghep_doc_2p),tong_sp_ghep_3,MaxTwoNum(tong_sp_ghep_ngang,tong_sp_ghep_doc));\r\n}   \r\n','','[\"7\",\"6\",\"13\",\"11\",\"22\",\"23\"]',36,'1616244609','1677558116'),(18,35,'Tính Tiền Giấy','tinh_tien_giay(so_luong_cap,loai_giay,dinh_luong,rong,dai)','function tinh_tien_giay(so_luong_cap,loai_giay,dinh_luong,rong,dai)\r\n{\r\n    var so_luong_to_ram=500;\r\n    var tien_ram_65_86 =lay_gia_ram_giay_65_86(loai_giay,dinh_luong);\r\n   // return tien_ram_65_86;\r\n    \r\n    var  tien_ram_79_109=lay_gia_ram_giay_79_109(loai_giay,dinh_luong);\r\n    var so_tien_mua_giay=0;\r\n    var tien_van_chuyen_giay= <tien_van_chuyen_giay>;\r\n    var tien_cat_giay=<cat_giay>;\r\n    if(so_luong_cap==0) return 0;\r\n    \r\n    var gia_giay_theo_kg =lay_gia_giay_kho_Lo_kg(loai_giay,dinh_luong);\r\n   \r\n   //  Tính trọng lượng giấy của 1 ream (kg) = (D * R * BW)/ 20000\r\n   // (20000 Là hằng số quy định)\r\n      var trong_Luong_1_ram =(rong*dai*dinh_luong)/20000;\r\n   \r\n      var trong_luong_1_to=trong_Luong_1_ram/so_luong_to_ram;\r\n      \r\n      so_tien_mua_giay = so_luong_cap*gia_giay_theo_kg*trong_luong_1_to+tien_cat_giay+tien_van_chuyen_giay;\r\n      \r\n    // 65x86n hard code cái chơi chứ hàm viết ko được\r\n    if(rong==65&&dai==86) so_tien_mua_giay=tien_ram_65_86*(so_luong_cap/so_luong_to_ram)+tien_van_chuyen_giay;\r\n   \r\n   // return tien_ram_65_86;\r\n     //return tien_ram_65_86*(so_luong_cap/so_luong_to_ram)+tien_van_chuyen_giay;\r\n    // // 79x109\r\n     if(rong==79&&dai==109)  so_tien_mua_giay=tien_ram_79_109*(so_luong_cap/so_luong_to_ram)+tien_van_chuyen_giay;\r\n // return tien_ram_65_86;\r\n return so_tien_mua_giay;\r\n}','[\"662\",\"660\"]','[\"8\",\"9\",\"20\",\"<tien_van_chuyen_giay>\"]',34,'1616244641','1677380595'),(19,30,'tinh_tien_in(cong_nghe_in,so_mau,rong,dai)','tinh_tien_in(cong_nghe_in,so_mau,rong,dai)','function tinh_tien_in(cong_nghe_in,so_mau,rong,dai)\r\n{\r\n    var so_tien_in=0;\r\n    // in offset\r\n        if( cong_nghe_in==1)\r\n    {\r\n        // kho in 52x72\r\n      if(rong<=50 && dai<=70 ||rong<=70 && dai<=50 )   so_tien_in= <tien_1_mau_in>*so_mau +<kem_52_72>*so_mau;\r\n       // khổ in 72x102\r\n      if(rong>50&& dai>70||rong>70&& dai>50) so_tien_in=<in_offset_ thuong_72_102>+ <kem_72_102>*so_mau;\r\n  \r\n    }\r\n    // in uv\r\n     if( cong_nghe_in==2)\r\n    {\r\n            // kho in 57x72\r\n        if(rong<=52 && dai<=72)   so_tien_in=<inoffsetUV_52_72>+ <kem_52_72>*so_mau;\r\n    \r\n        // khổ in 72x102\r\n         if(rong>52&& dai>72) so_tien_in=<inoffsetUV_72_102>+ <kem_72_102>*so_mau;\r\n  \r\n    }\r\n // khổ in 37x52\r\n return so_tien_in;\r\n}','[\"794\",\"792\",\"790\",\"793\",\"789\",\"791\",\"795\"]','',35,'1616244667','1677298200'),(20,0,'Lấy Giá Giấy Khổ Lỡ theo Kg','lay_gia_giay_kho_Lo_kg(loai_giay,dinh_luong)','function lay_gia_giay_kho_Lo_kg(loai_giay,dinh_luong){\r\n    \r\n    var gia_giay_kg=0;\r\n     // định lượng 200 g/m2\r\n      if(dinh_luong==100 )\r\n    {\r\n            // ivory\r\n          //  if(loai_giay==\"I\") gia_giay_kg =<Ivory_200>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_giay_kg= <Couche_100>;          \r\n             \r\n             // Briston (C Pindo)\r\n          // if(loai_giay==\"B\")   gia_giay_kg=  <Briston_200>;\r\n            \r\n             // Duplex\r\n          //  if(loai_giay==\"D\") gia_giay_kg= <Duplex_200>;\r\n         \r\n    }\r\n      if(dinh_luong==120 )\r\n    {\r\n            // ivory\r\n          //  if(loai_giay==\"I\") gia_giay_kg =<Ivory_200>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_giay_kg= <Couche_120>;          \r\n             \r\n             // Briston (C Pindo)\r\n          // if(loai_giay==\"B\")   gia_giay_kg=  <Briston_200>;\r\n            \r\n             // Duplex\r\n          //  if(loai_giay==\"D\") gia_giay_kg= <Duplex_200>;\r\n         \r\n    }\r\n      if(dinh_luong==120||dinh_luong==120 )\r\n    {\r\n            // ivory\r\n          //  if(loai_giay==\"I\") gia_giay_kg =<Ivory_200>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_giay_kg= <Couche_150>;          \r\n             \r\n             // Briston (C Pindo)\r\n          // if(loai_giay==\"B\")   gia_giay_kg=  <Briston_200>;\r\n            \r\n             // Duplex\r\n          //  if(loai_giay==\"D\") gia_giay_kg= <Duplex_200>;\r\n         \r\n    }\r\n     if(dinh_luong==200 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_giay_kg =<Ivory_200>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_giay_kg= <Couche_200>;          \r\n             \r\n             // Briston (C Pindo)\r\n           if(loai_giay==\"B\")   gia_giay_kg=  <Briston_200>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_giay_kg= <Duplex_200>;\r\n         \r\n    }\r\n     // định lượng 250 g/m2\r\n     if(dinh_luong==250 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_giay_kg =<Ivory_250>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_giay_kg= <Couche_250>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_giay_kg=  <Briston_250>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_giay_kg= <Duplex_250>;\r\n         \r\n    }\r\n    // định lượng 300 g/m2\r\n    if(dinh_luong==300 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_giay_kg =<Ivory_300>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_giay_kg= <Couche_300>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\") gia_giay_kg= <Briston_300>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_giay_kg= <Duplex_300>;\r\n         \r\n    }\r\n    \r\n   // định lượng 350 g/m2\r\n    if(dinh_luong==350 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_giay_kg =<Ivory_350>;\r\n          \r\n             // Couches bóng\r\n            if(loai_giay==\"C\")  gia_giay_kg= <Couche_350>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_giay_kg= <Briston_350>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_giay_kg= <Duplex_350>;\r\n         \r\n    }\r\n     // định lượng 400 g/m2\r\n    if(dinh_luong==400||dinh_luong==450 )\r\n    {\r\n            // ivory\r\n            if(loai_giay==\"I\") gia_giay_kg =<Ivory_400>;\r\n          \r\n             // Couches bóng -\r\n            if(loai_giay==\"C\")  gia_giay_kg= <Couche_400>;          \r\n             \r\n             // Briston (C Pindo)\r\n            if(loai_giay==\"B\")   gia_giay_kg= <Briston_400>;\r\n            \r\n             // Duplex\r\n            if(loai_giay==\"D\") gia_giay_kg= <Duplex_400>;\r\n         \r\n    }\r\n    \r\n  return gia_giay_kg;\r\n}','[\"674\",\"704\",\"933\",\"725\",\"676\",\"706\",\"935\",\"727\",\"677\",\"707\",\"934\",\"728\",\"678\",\"708\",\"736\",\"729\",\"679\",\"936\",\"737\",\"730\",\"701\",\"702\",\"703\"]','',34,'1616654754','1677380912'),(21,2,'Tính Tiền Cán Màng','tinh_tien_can_mang(so_luong,kho_trai_ngang,kho_trai_cao,can_mang,so_mat_can)','function tinh_tien_can_mang(so_luong,kho_trai_ngang,kho_trai_cao,can_mang,so_mat_can)\r\n{\r\n    var tien_can_mang =0;\r\n   // Cán Màng Bóng\r\n    if(can_mang==1) tien_can_mang=so_mat_can*so_luong*<can_mang_bong_nhiet>*(kho_trai_ngang*kho_trai_cao)/10000;\r\n    // Cán Màng Mờ\r\n    if(can_mang==2) tien_can_mang=so_mat_can*so_luong*<can_mang_mo_nhiet>*(kho_trai_ngang*kho_trai_cao)/10000;\r\n   \r\n    //nếu số tiền quá nhỏ thì sẽ tính theo lô\r\n    if(tien_can_mang<=<tien_can_mang_theo_lo>)\r\n    tien_can_mang=<tien_can_mang_theo_lo>;\r\n    \r\n  return tien_can_mang;\r\n}','[\"808\",\"809\",\"895\"]','',35,'1616665865','1617259208'),(22,98,'tính khổ trải ngang túi giấy','tinh_kho_trai_ngang_tg(dai, rong,kieu_tui)','// tính khổ trải ngang túi giấy\r\nfunction tinh_kho_trai_ngang_tg(dai, rong,kieu_tui){\r\n  var kho_trai_ngang=0;\r\n  \r\n  //Túi xỏ dây -(Dài+rộng)x2+2\r\n  if(kieu_tui==30)kho_trai_ngang =(dai+rong)*2+2;\r\n  \r\n  //Túi quai xách không xỏ dây-(Dài+rộng)x2+2\r\n  if(kieu_tui==31)kho_trai_ngang =(dai+rong)*2+2;\r\n  \r\n  //Túi quai xách đáy gài-(Dài+rộng)x2+2\r\n  if(kieu_tui==32)kho_trai_ngang =(dai+rong)*2+2;\r\n    if(kho_trai_ngang>0.2)kho_trai_ngang=kho_trai_ngang +0.2;\r\n    else kho_trai_ngang=0;\r\n    \r\n //túi ruy băng \r\n  if(kieu_tui==33)kho_trai_ngang =(dai+rong)*2+2;\r\n    \r\n   return  kho_trai_ngang ;\r\n}','','',36,'1617079401','1677137600'),(23,99,'tính khổ trải cao túi giấy','tinh_kho_trai_cao_tg(cao, rong,kieu_tui)','function tinh_kho_trai_cao_tg(cao, rong,kieu_tui){\r\n    var kho_trai_cao =0;\r\n    //Túi xỏ dây -Cao+Cao/5+(2/3 rộng)\r\n    if(kieu_tui==30)kho_trai_cao = cao+cao/5 + (2*rong)/3;\r\n    \r\n    //Túi quai xách không xỏ dây- Cao+7+(2/3 rộng)\r\n    if(kieu_tui==31)kho_trai_cao = cao+7+ 2*rong/3;\r\n    \r\n    //Túi quai xách đáy gài-Cao+7x2+rộng/2+2\r\n    if(kieu_tui==32)kho_trai_cao = cao+ 7*2 + rong/2 + 2;\r\n    \r\n    // túi ruy băng\r\n     if(kieu_tui==33)kho_trai_cao = cao+ 6 + rong/2 +3;\r\n     \r\n     \r\n     if (kho_trai_cao>0.2)   return  kho_trai_cao + 0.2;\r\n     else return 0;\r\n   \r\n}','','',36,'1617079568','1677137752'),(24,0,'Tính tiền ép kim','tinh_tien_ep_kim(so_luong,dien_tich)','function tinh_tien_ep_kim(so_luong,dien_tich){\r\n    \r\n    var tien_ep_kim=0;\r\n    var gia_gia_cong_sp=0;\r\n    var gia_min_ep_kim_cm2=<gia_min_ep_kim_cm2>;\r\n   // var gia_ep_kim_max_tren_sp=<gia_ep_kim_max_tren_sp>;\r\n    var gia_ep_kim_max_dien_tich_sp= <gia_ep_kim_max_dien_tich_sp>;\r\n   // var gia_ep_kim_max_tren_sp =<gia_ep_kim_max_tren_sp>;\r\n    var gia_khuon =<gia_khuon_ep_kim>;\r\n    var gia_khuon_ep_kim_cm2= <gia_khuon_ep_kim_cm2>;\r\n    var gia_ep_kim_min_tren_sp =<gia_ep_kim_min_tren_sp>;\r\n    var gia_ep_kim_max_tren_sp =<gia_ep_kim_max_tren_sp>;\r\n   // return 0;\r\n    //tính tiền khuôn thì khuôn lớn\r\n    if( dien_tich*gia_min_ep_kim_cm2>=gia_ep_kim_max_tren_sp||dien_tich*gia_ep_kim_max_dien_tich_sp >=gia_ep_kim_max_tren_sp)\r\n \r\n   {\r\n       gia_khuon=dien_tich*gia_khuon_ep_kim_cm2;//<gia_khuon_ep_kim_cm2>;\r\n       gia_gia_cong_sp= gia_ep_kim_min_tren_sp;\r\n       tien_ep_kim =gia_gia_cong_sp*so_luong;\r\n    }\r\n    else \r\n       {\r\n          gia_gia_cong_sp=<gia_ep_kim_max_tren_sp>;\r\n          tien_ep_kim =gia_gia_cong_sp*so_luong;\r\n         }\r\n     \r\n    if(dien_tich==0) return 0;\r\n    if(tien_ep_kim<=<gia_ep_kim_theo_lo>) tien_ep_kim=<gia_ep_kim_theo_lo>;\r\n    \r\n    tien_ep_kim=tien_ep_kim+gia_khuon;\r\n    \r\n    return tien_ep_kim;\r\n    \r\n}','[\"903\",\"906\",\"904\",\"896\",\"898\",\"908\",\"905\"]','',35,'1617261117','1617789497'),(25,0,'Tính tiền bế nổi','tinh_tien_be_noi(so_luong,dien_tich)','function tinh_tien_be_noi(so_luong,dien_tich){\r\n    var tien_be_noi=0;\r\n    var gia_gia_cong_sp=0;\r\n    var gia_min_be_noi_cm2=<gia_min_be_noi_cm2>;\r\n   \r\n    var gia_be_noi_max_cm2= <gia_be_noi_max_cm2>;\r\n   \r\n    var gia_khuon =<gia_khuon_be_noi>;\r\n    var gia_khuon_be_noi_cm2= <gia_khuon_be_noi_cm2>;\r\n     \r\n    var gia_be_noi_min_tren_sp =<gia_be_noi_min_tren_sp>;\r\n    var gia_be_noi_max_tren_sp =<gia_be_noi_max_tren_sp>;\r\n  \r\n    //tính tiền khuôn thì khuôn lớn\r\n    if( dien_tich*gia_min_be_noi_cm2>=gia_be_noi_max_tren_sp||dien_tich*gia_be_noi_max_cm2 >=gia_be_noi_max_tren_sp)\r\n \r\n   {\r\n       gia_khuon=dien_tich*gia_khuon_be_noi_cm2;//<gia_khuon_be_noi_cm2>;\r\n      gia_gia_cong_sp=gia_be_noi_min_tren_sp;\r\n       tien_be_noi =gia_gia_cong_sp*so_luong;\r\n    }\r\n    else \r\n       {\r\n          gia_gia_cong_sp=gia_be_noi_max_tren_sp;\r\n          tien_be_noi =gia_gia_cong_sp*so_luong;\r\n        }\r\n     \r\n    if(dien_tich==0) return 0;\r\n    if(tien_be_noi<=<gia_be_noi_theo_lo>) tien_be_noi=<gia_be_noi_theo_lo>;\r\n        tien_be_noi=tien_be_noi+gia_khuon;\r\n    \r\n    return tien_be_noi;\r\n}','[\"910\",\"912\",\"915\",\"909\",\"913\",\"911\",\"914\"]','',35,'1617263307','1617789558'),(26,0,'tính tiền tráng phủ','tinh_tien_trang_phu(so_luong,dai,rong,trang_phu,so_lan_trang_phu)','function tinh_tien_trang_phu(so_luong,dai,rong,trang_phu,so_lan_trang_phu){\r\n    var tien_trang_phu=0;\r\n    \r\n    if(trang_phu==0)\r\n      tien_trang_phu=0;\r\n      \r\n      if(trang_phu==1)\r\n      {\r\n         tien_trang_phu= (so_luong*dai*rong*<UV toàn phần bóng>)/10000;\r\n         var lo= <UV toàn phần bóng lô>;\r\n         if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n\r\n      }\r\n      if(trang_phu==2)\r\n      {\r\n        tien_trang_phu= (so_luong*dai*rong*<UV toàn phần mờ>)/10000;\r\n          var lo= <UV toàn phần mờ lô>;\r\n         if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n      }\r\n      if(trang_phu==3)\r\n         {\r\n           tien_trang_phu= (so_luong*dai*rong*<Phủ nhung>)/10000;\r\n           var lo= <Phủ nhung lô>;\r\n          if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n        }\r\n         if(trang_phu==4){\r\n        tien_trang_phu= (so_luong*dai*rong*<UV định hình>)/10000;\r\n         var lo= <UV định hình lô>;\r\n          if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n        }\r\n         if(trang_phu==5)\r\n         {\r\n        tien_trang_phu= (so_luong*dai*rong*<Varnish offset>)/10000;\r\n         var lo= <Varnish offset lô>;\r\n          if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n        }\r\n         if(trang_phu==6)\r\n         {\r\n        tien_trang_phu= (so_luong*dai*rong*<Varnish thủy tính>)/10000;\r\n         var lo= <Varnish thủy tính lô>;\r\n          if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n        }\r\n         if(trang_phu==7)\r\n         {\r\n          tien_trang_phu= (so_luong*dai*rong*<Varnish thủy tính mờ>)/10000;\r\n          \r\n           var lo= <Varnish thủy tính mờ lô>;\r\n          if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n        }\r\n         if(trang_phu==8)\r\n         {\r\n        tien_trang_phu= (so_luong*dai*rong*<Calendering>)/10000;\r\n          var lo= <Calendering lô>;\r\n          if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n        }\r\n         if(trang_phu==9)\r\n         {\r\n        tien_trang_phu= (so_luong*dai*rong*<Chiết quang (hologram)>)/10000;\r\n        var lo= <Chiết quang (hologram) lô>;\r\n          if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n        }\r\n        \r\n         if(trang_phu==10)\r\n         {\r\n        tien_trang_phu= (so_luong*dai*rong*<Xử lý primer>)/10000;\r\n         var lo= <Xử lý primer lô>;\r\n          if(tien_trang_phu<=lo) tien_trang_phu=lo;\r\n        }\r\n        \r\n        \r\n    return so_lan_trang_phu*tien_trang_phu; \r\n}','[\"796\",\"797\",\"798\",\"799\",\"800\",\"801\",\"803\",\"804\",\"805\",\"802\",\"916\",\"917\",\"918\",\"919\",\"920\",\"921\",\"922\",\"923\",\"924\",\"925\"]','',35,'1617264154','1617437564'),(27,0,'tính tiền phủ cat','tinh_tien_phu_cat(so_luong,dai,rong,phu_cat)','function tinh_tien_phu_cat(so_luong,dai,rong,phu_cat){\r\n    var tien_phu_cat =0;\r\n    tien_phu_cat =(phu_cat*so_luong*dai*rong*<gia_phu_cat_theo_m2>)/10000;\r\n    if(tien_phu_cat==0)return  0;\r\n    if(tien_phu_cat<=<phu_cat_theo_lo>)tien_phu_cat=<phu_cat_theo_lo>;\r\n    return tien_phu_cat;\r\n}','[\"901\",\"902\"]','',35,'1617265583','1617265783'),(28,0,'Tính tiền metalize ','tinh_tien_ghep_metalize(so_luong,dai,rong,cong_nghe_in)','function tinh_tien_ghep_metalize(so_luong,dai,rong,cong_nghe_in)\r\n{\r\n    var tinh_tien_ghep_metalize =0;\r\n    //in metalize thì phải ghép màng metalize\r\n    if(cong_nghe_in==2)\r\n    {\r\n        tinh_tien_ghep_metalize=<can_mang_metalize_bac>*(so_luong*dai*rong)/10000;\r\n        var lo =<can_mang_metalize_lo>\r\n        if(tinh_tien_ghep_metalize<=lo)tinh_tien_ghep_metalize=lo;\r\n    }\r\n    return tinh_tien_ghep_metalize\r\n}','[\"894\",\"926\"]','',35,'1617439707','1617440277'),(29,0,'Tính tiền gia công bế','tinh_tien_be(so_luong,so_lan)','function tinh_tien_be(so_luong,so_lan)\r\n{\r\n    var tien_be =0;\r\n    var tien_khuon_be =<gia_khuon_be>;\r\n    var tien_be_theo_lo=<gia_be_theo_lo>;\r\n    var tien_luot_be=<be_tu_dong>;\r\n   // return tien_luot_be;\r\n     tien_be =tien_luot_be*so_luong;\r\n    // return tien_be;\r\n    if(tien_luot_be*so_luong<=tien_be_theo_lo) tien_be=tien_be_theo_lo;\r\n      \r\n     tien_be =so_lan*tien_be + tien_khuon_be;\r\n     \r\n    return  tien_be;\r\n}','[\"927\",\"928\",\"835\"]','',37,'1617441502','1617443000'),(30,0,'tính tiền dan hộp','tien_dan_hop(so_luong,loai_dan)','function tien_dan_hop(so_luong,loai_dan)\r\n{\r\n     var tien_dan_hop =0;\r\n     var dan_may=  <dan_may>;\r\n     var dan_tay= <dan_tay>;\r\n     var gia_tien_dan=0;\r\n    var dan_hop_lo =<dan_hop_lo>;\r\n   \r\n    if(loai_dan==\"dan_may\")gia_tien_dan=dan_may;\r\n    if(loai_dan==\"dan_tay\")gia_tien_dan=dan_tay;\r\n    \r\n    //return gia_tien_dan;\r\n    tien_dan_hop=gia_tien_dan*so_luong;\r\n    \r\n    if(tien_dan_hop<=dan_hop_lo)tien_dan_hop=dan_hop_lo;\r\n   return tien_dan_hop;\r\n}','[\"929\",\"837\",\"836\"]','',37,'1617443285','1617594634'),(31,0,'tính tiền dán support nếu có','tien_dan_support(so_luong,chat_lieu_dan_cua_so,dien_tich_cua_so)','function tien_dan_support(so_luong,chat_lieu_dan_cua_so,dien_tich_cua_so)\r\n{\r\n    var tien_dan_cua_so=<dan_cua_so>;\r\n    var tien_dan_support_lo =<dan_support_lo>;\r\n    var gia_tren_m2=0;\r\n    var tien_gia_cong =0;\r\n   // return <dan_cua_so>;\r\n    if(chat_lieu_dan_cua_so==\"PE0.05mm\") gia_tren_m2=<PE 0.05mm>;\r\n    \r\n    if(chat_lieu_dan_cua_so==\"PET0.15mm\")gia_tren_m2=<PET 0.15mm>;\r\n    \r\n    if(chat_lieu_dan_cua_so==\"PET0.1mm\")gia_tren_m2=<PET 0.1mm>;\r\n    \r\n   if(chat_lieu_dan_cua_so==\"PET0.25mm\")gia_tren_m2=<PET 0.25mm>;\r\n    \r\n    if(chat_lieu_dan_cua_so==\"PET0.2mm\")gia_tren_m2=<PET 0.2mm>;\r\n    \r\n    if(chat_lieu_dan_cua_so==\"PET0.3mm\")gia_tren_m2=<PET 0.3mm>;\r\n    \r\n    if(chat_lieu_dan_cua_so==\"PVC0.15mm\")gia_tren_m2=<PVC 0.15mm>;\r\n    \r\n    if(chat_lieu_dan_cua_so==\"PVC0.1mm\")gia_tren_m2=<PVC 0.1mm>;\r\n    \r\n    if(chat_lieu_dan_cua_so==\"PVC0.25mm\")gia_tren_m2=<PVC 0.25mm>;\r\n    \r\n    if(chat_lieu_dan_cua_so==\"PVC0.2mm\")gia_tren_m2=<PVC 0.2mm>;\r\n    \r\n    tien_gia_cong=(gia_tren_m2*so_luong*dien_tich_cua_so)/10000;\r\n    \r\n    if(tien_gia_cong<=tien_dan_support_lo)tien_gia_cong=tien_dan_support_lo;\r\n    \r\n    return tien_gia_cong;\r\n}\r\n','[\"853\",\"854\",\"855\",\"856\",\"857\",\"858\",\"859\",\"860\",\"861\",\"862\",\"839\",\"930\"]','',37,'1617596979','1617604129'),(32,0,'tính tiền bồi giấy','tinh_tien_boi(so_luong,kho_trai_ngang,kho_trai_cao,boi_giay)','function tinh_tien_boi(so_luong,kho_trai_ngang,kho_trai_cao,boi_giay)\r\n{\r\n    var tien_boi_giay =0;\r\n    var tien_cong_boi_tren_lo=<tien_cong_boi_tren_lo>;\r\n    var tien_cong_boi_m2=<tien_cong_boi_m2>;\r\n    var tien_mua_giay=0;\r\n    tien_boi_giay= (so_luong*kho_trai_ngang*kho_trai_cao*tien_cong_boi_m2)/10000;\r\n   if(tien_boi_giay<=tien_cong_boi_tren_lo)tien_boi_giay=tien_cong_boi_tren_lo;\r\n    if(boi_giay==0) return 0;\r\n   \r\n      //Sóng A 2 lớp\r\n     if(boi_giay==2)   tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng A 2 lớp>)/10000;\r\n     //Sóng AB\r\n      if(boi_giay==3)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng AB>)/10000;\r\n        //Sóng B\r\n      if(boi_giay==4)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng B>)/10000;\r\n      //Sóng B 2 lớp\r\n      if(boi_giay==5)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng B 2 lớp> )/10000;\r\n    //Sóng BE\r\n      if(boi_giay==6)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng BE> )/10000;\r\n     //Sóng E\r\n      if(boi_giay==7)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng E> )/10000;\r\n    //Sóng E 2 lớp\r\n      if(boi_giay==8)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng E 2 lớp> )/10000;\r\n    //Sóng E 2 xeo\r\n      if(boi_giay==9)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng E 2 xeo>  )/10000;\r\n    //Sóng E 3 lớp\r\n      if(boi_giay==10)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng E 3 lớp>  )/10000;\r\n\r\n   //Sóng EB chống thấm\r\n      if(boi_giay==11)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng EB chống thấm>   )/10000;\r\n\r\n\r\n    return tien_boi_giay+tien_mua_giay;\r\n}','[\"778\",\"931\",\"932\",\"779\",\"780\",\"781\",\"782\",\"783\",\"784\",\"785\",\"786\",\"787\"]','',35,'1617610313','1617611379'),(33,0,'Tính khổ trải ngang của hộp giấy âm dương',' tinh_kho_trai_ngang_am_duong(dai,rong, cao, kieu_hop,do_day_thanh,loai)','function tinh_kho_trai_ngang_am_duong(dai,rong, cao, kieu_hop,do_day_thanh,loai) {\r\n\r\n  var kho_trai_ngang =0;\r\n    \r\n    //Dài+(cao-1)x4+1.5*2\r\n    if (kieu_hop == 20 &&loai==\"nap\") kho_trai_ngang= dai + (cao-1) * 4 + 1.5*2;\r\n   //Dài-0.3+cao*4+1.5*2\r\n    if (kieu_hop == 20 &&loai==\"day\") kho_trai_ngang= dai -0.3 + (cao) * 4 + 1.5*2;\r\n\r\n  \r\n    //Dài+(cao-1)*4+1.5*2\r\n    if (kieu_hop == 21 &&loai==\"nap\") kho_trai_ngang= dai + (cao-1) * 4 + 1.5*2;\r\n   //Dài-0.3+cao*4+1.5*2+x*2\r\n    if (kieu_hop == 21 &&loai==\"day\") kho_trai_ngang= dai -0.3 + (cao) * 4 + 1.5*2+do_day_thanh*2;\r\n \r\n     //(Rộng+cao+0.3)*2+1.5\r\n    if (kieu_hop == 22 &&loai==\"nap\") kho_trai_ngang= (rong + cao+0.3)+1.5\r\n   //Dài+cao*4+1.5*2+x*2\r\n    if (kieu_hop == 22 &&loai==\"day\") kho_trai_ngang= dai +cao*+1.5*2+do_day_thanh*2;\r\n\r\n     if(kho_trai_ngang>0.2)kho_trai_ngang=kho_trai_ngang+0.2;\r\n     else kho_trai_ngang=0;\r\n     \r\n     return kho_trai_ngang;\r\n}','','',36,'1617782036','1618019556'),(34,0,'Tính khổ trải cao của hộp giấy âm dương','tinh_kho_trai_cao_am_duong(dai, rong,cao, kieu_hop,do_day_thanh,loai)','function tinh_kho_trai_cao_am_duong(dai, rong,cao, kieu_hop,do_day_thanh,loai) {\r\n    \r\n   var kho_trai_cao =0;\r\n   \r\n   //Rộng+(cao-1)x4+1.5*2\r\n   if (kieu_hop==20 && loai==\"nap\") kho_trai_cao= rong+(cao-1)*4+1.5*2;\r\n   //Rộng-0.3+cao*4+1.5*2\r\n   if (kieu_hop==20 && loai==\"day\") kho_trai_cao= rong-0.3+cao*4+1.5*2;\r\n   \r\n   //Rộng+(cao-1)*4+1.5*2\r\n   if (kieu_hop==21 && loai==\"nap\") kho_trai_cao=rong+(cao-1)*4+1.5*2\r\n   //Rộng-0.3+cao*4+1.5*2+x*2\r\n   if (kieu_hop==21 && loai==\"day\") kho_trai_cao= rong-0.3+cao*4+1.5*2+do_day_thanh*2;\r\n    \r\n     //dai\r\n   if (kieu_hop==22 && loai==\"nap\") kho_trai_cao=dai;\r\n   //Rộng+cao*4+1.5*2+x*2\r\n   if (kieu_hop==22 && loai==\"day\") kho_trai_cao= rong+cao*4+1.5*2+do_day_thanh*2;\r\n   if(kho_trai_cao>0.2)kho_trai_cao=kho_trai_cao+0.2;\r\n   else kho_trai_cao=0;\r\n     return kho_trai_cao;\r\n}','','',36,'1617782187','1677558215'),(35,0,'tính số sản phẩm trên tờ của hộp giấy âm dương','lay_so_sp_tren_to_hop_am_duong(ktc,ktn,kieu_hop,rong_kho_giay,dai_kho_giay)','function lay_so_sp_tren_to_hop_am_duong(ktc,ktn,kieu_hop,rong_kho_giay,dai_kho_giay){\r\n      \r\n     var kho_trai_cao=0;//=tinh_kho_trai_cao(cao, rong, kieu_hop);\r\n     var kho_trai_ngang=0;//=tinh_kho_trai_ngang(dai,rong, kieu_hop);\r\n     \r\n       // nếu là hộp giấy - am dương\r\n         kho_trai_cao=ktc;\r\n         kho_trai_ngang=ktn;\r\n    \r\n     if(ktc==0||ktn==0) return 0;\r\n     \r\n     var kho_trai_cao_2_sp =kho_trai_cao*2;\r\n     var kho_trai_cao_3_sp =kho_trai_cao*3;\r\n     //return kho_trai_cao;\r\n    \r\n     // kiểu ghép hộp ngang\r\n     var tong_sp_ghep_ngang=0;\r\n     var so_sp_xep_ngang_ghep_ngang=0;\r\n     var so_sp_xep_doc_ghep_ngang=0;\r\n     tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n     \r\n      // kiểu ghép hộp dọc\r\n     var tong_sp_ghep_doc=0;\r\n     var so_sp_xep_ngang_ghep_doc=0;\r\n     var so_sp_xep_doc_ghep_doc=0;\r\n     tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n     // số lượng sản trên tờ \r\n       \r\n     // nếu kiểu hộp rơi vào Hộp dán hông đáy xếp, 1 khóa gài hoặc Hộp dán hông 2 khóa cài (RTE)\r\n     \r\n     // kiểu ghép hộp ngang 2 sp\r\n     var tong_sp_ghep_ngang_2p=0;\r\n     var so_sp_xep_ngang_ghep_ngang_2p=0;\r\n     var so_sp_xep_doc_ghep_ngang_2p=0;\r\n     tong_sp_ghep_ngang_2p=so_sp_xep_ngang_ghep_ngang_2p*so_sp_xep_doc_ghep_ngang_2p;\r\n     \r\n      // kiểu ghép hộp dọc 2p\r\n     var tong_sp_ghep_doc_2p=0;\r\n     var so_sp_xep_ngang_ghep_doc_2p=0;\r\n     var so_sp_xep_doc_ghep_doc_2p=0;\r\n     tong_sp_ghep_doc_2p=so_sp_xep_ngang_ghep_doc_2p*so_sp_xep_doc_ghep_doc_2p;\r\n     // số lượng sản trên tờ \r\n    \r\n     var max_sp_ghep =0;\r\n     if(kieu_hop==1||kieu_hop ==2||kieu_hop ==3)\r\n     {\r\n        \r\n           kho_trai_cao_2_sp=kho_trai_cao_2_sp-(rong + 2);\r\n          \r\n          // trường hợp ghép ngang  an gian giấy\r\n     \r\n          so_sp_xep_ngang_2p=2*Math.floor(dai_kho_giay/kho_trai_cao_2_sp);\r\n         \r\n          so_sp_xep_doc_ghep_ngang_2p=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          tong_sp_ghep_ngang_2p=so_sp_xep_ngang_2p*so_sp_xep_doc_ghep_ngang_2p;\r\n          \r\n        // trường hợp ghép dọc  an giấy\r\n            so_sp_xep_ngang_ghep_doc_2p=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n            so_sp_xep_doc_ghep_doc_2p=2*Math.floor(rong_kho_giay/kho_trai_cao_2_sp);\r\n            tong_sp_ghep_doc_2p=so_sp_xep_ngang_ghep_doc_2p*so_sp_xep_doc_ghep_doc_2p;\r\n       \r\n     }\r\n     // trường hợp 4,5 phải cộng 1.2cm\r\n     \r\n     if(kieu_hop ==4||kieu_hop ==5||kieu_hop ==6)\r\n     {\r\n        \r\n           kho_trai_cao_2_sp=kho_trai_cao_2_sp-(rong + 2)+1.2;\r\n          \r\n          // trường hợp ghép ngang  an gian giấy\r\n     \r\n          so_sp_xep_ngang_2p=2*Math.floor(dai_kho_giay/kho_trai_cao_2_sp);\r\n         \r\n          so_sp_xep_doc_ghep_ngang_2p=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          tong_sp_ghep_ngang_2p=so_sp_xep_ngang_2p*so_sp_xep_doc_ghep_ngang_2p;\r\n          \r\n        // trường hợp ghép dọc  an giấy\r\n            so_sp_xep_ngang_ghep_doc_2p=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n            so_sp_xep_doc_ghep_doc_2p=2*Math.floor(rong_kho_giay/kho_trai_cao_2_sp);\r\n            tong_sp_ghep_doc_2p=so_sp_xep_ngang_ghep_doc_2p*so_sp_xep_doc_ghep_doc_2p;\r\n       \r\n     }\r\n     var tong_sp_ghep_3=0;\r\n     \r\n    //Hộp nắp mở 2 đáy an gian giấy ghép 3\r\n     if (kieu_hop==1)\r\n     {  \r\n         // return kho_trai_cao_3_sp;\r\n         kho_trai_cao_3_sp=kho_trai_cao_3_sp-2*(rong + 2);\r\n          //return kho_trai_cao_3_sp;\r\n        // trường hợp ghép ngang  an gian giấy\r\n         \r\n         var so_sp_xep_ngang_3p=3*Math.floor(dai_kho_giay/kho_trai_cao_3_sp);\r\n           //return so_sp_xep_ngang_3p;\r\n         var so_sp_xep_doc_ghep_ngang_3p=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n              //return so_sp_xep_doc_ghep_ngang_3p;\r\n          var tong_sp_ghep_ngang_3p=so_sp_xep_ngang_3p*so_sp_xep_doc_ghep_ngang_3p;\r\n          \r\n        // trường hợp ghép dọc an giấy\r\n      \r\n          var  so_sp_xep_ngang_ghep_doc_3p=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n          // return so_sp_xep_ngang_ghep_doc_3p;\r\n          var  so_sp_xep_doc_ghep_doc_3p=3*Math.floor(rong_kho_giay/kho_trai_cao_3_sp);\r\n             //return so_sp_xep_doc_ghep_doc_3p;\r\n             //return so_sp_xep_doc_ghep_doc_3p;\r\n           var tong_sp_ghep_doc_3p=so_sp_xep_doc_ghep_doc_3p*so_sp_xep_ngang_ghep_doc_3p;\r\n           \r\n           tong_sp_ghep_3=MaxTwoNum(tong_sp_ghep_ngang_3p,tong_sp_ghep_doc_3p);\r\n     }\r\n     //Hộp nắp mở 2 đáy khóa 2 đầu an gian giấy ghép 3 phải cộng 1.2\r\n     if (kieu_hop==4||kieu_hop==6)\r\n     {  \r\n         // return kho_trai_cao_3_sp;\r\n         kho_trai_cao_3_sp=kho_trai_cao_3_sp-2*(rong + 2+1.2);\r\n          //return kho_trai_cao_3_sp;\r\n        // trường hợp ghép ngang  an gian giấy\r\n         \r\n         var so_sp_xep_ngang_3p=3*Math.floor(dai_kho_giay/kho_trai_cao_3_sp);\r\n           //return so_sp_xep_ngang_3p;\r\n         var so_sp_xep_doc_ghep_ngang_3p=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n              //return so_sp_xep_doc_ghep_ngang_3p;\r\n          var tong_sp_ghep_ngang_3p=so_sp_xep_ngang_3p*so_sp_xep_doc_ghep_ngang_3p;\r\n          \r\n        // trường hợp ghép dọc an giấy\r\n      \r\n          var  so_sp_xep_ngang_ghep_doc_3p=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n          // return so_sp_xep_ngang_ghep_doc_3p;\r\n          var  so_sp_xep_doc_ghep_doc_3p=3*Math.floor(rong_kho_giay/kho_trai_cao_3_sp);\r\n             //return so_sp_xep_doc_ghep_doc_3p;\r\n             //return so_sp_xep_doc_ghep_doc_3p;\r\n           var tong_sp_ghep_doc_3p=so_sp_xep_doc_ghep_doc_3p*so_sp_xep_ngang_ghep_doc_3p;\r\n           \r\n           tong_sp_ghep_3=MaxTwoNum(tong_sp_ghep_ngang_3p,tong_sp_ghep_doc_3p);\r\n     }\r\n     \r\n       // trường hợp ghép ngang không an gian giấy\r\n \r\n          so_sp_xep_ngang_ghep_ngang=Math.floor(dai_kho_giay/kho_trai_cao);\r\n         // return so_sp_xep_ngang;  \r\n          so_sp_xep_doc_ghep_ngang=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          \r\n          tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n          \r\n       // trường hợp ghép dọc\r\n   \r\n        so_sp_xep_ngang_ghep_doc=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n         \r\n        so_sp_xep_doc_ghep_doc=Math.floor(rong_kho_giay/kho_trai_cao);\r\n        \r\n        tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n        \r\n        var tong=0;\r\n        \r\n      tong =  MaxThreeNum( MaxTwoNum(tong_sp_ghep_ngang_2p,tong_sp_ghep_doc_2p),tong_sp_ghep_3,MaxTwoNum(tong_sp_ghep_ngang,tong_sp_ghep_doc));\r\n      if(tong==0) tong=1;\r\n      return tong;\r\n}   ','','[\"13\"]',36,'1617786401','1646277606'),(36,0,'Tính tiền dán túi giấy',' tien_dan_tui_giay(so_luong,loai_dan)','function tien_dan_tui_giay(so_luong,loai_dan)\r\n{\r\n    var dan_tui_giay_bang_may= <dan_tui_giay_bang_may>;\r\n    var dan_tui_giay_bang_tay=<dan_tui_giay_bang_tay>;\r\n    var dan_tui_giay_theo_lo=<dan_tui_giay_theo_lo>;\r\n    var tong_tien_dan=0;\r\n    if(loai_dan==\"dan_may\") tong_tien_dan=dan_tui_giay_bang_may*so_luong;\r\n    if(loai_dan==\"dan_tay\")tong_tien_dan=dan_tui_giay_bang_tay*so_luong;\r\n    if(tong_tien_dan<=dan_tui_giay_theo_lo)tong_tien_dan=dan_tui_giay_theo_lo;\r\n    return tong_tien_dan;\r\n}','[\"838\",\"938\",\"939\"]','',37,'1617849343','1617849949'),(37,0,'Tính tiền quay xách','tinh_tien_quay_xach(so_luong,kieu_hop,quay_xach)','function tinh_tien_quay_xach(so_luong,kieu_hop,quay_xach)\r\n{\r\n    var tien_quay_xach=0;\r\n    // túi  quay xách\r\n    if(kieu_hop==30)\r\n    {\r\n        if(quay_xach==1)tien_quay_xach =so_luong*<quay_du_thuong>;\r\n         if(quay_xach==2)tien_quay_xach =so_luong*<quai_du_cao_cap>;\r\n        \r\n    }\r\n    //  túi ruy băng\r\n    if(kieu_hop==33)\r\n    {\r\n       \r\n        if(quay_xach==1)tien_quay_xach =so_luong*(<quay_du_thuong>+<gia_ruby_bang>);\r\n         if(quay_xach==2)tien_quay_xach =so_luong*(<quai_du_cao_cap>+<gia_ruby_bang>);\r\n        \r\n    }\r\n    return tien_quay_xach;\r\n    \r\n}\r\n','[\"940\",\"941\",\"996\"]','',37,'1617856534','1677311399'),(38,101,'format money ','formatMoney(number)','function formatMoney(number)\r\n{\r\n//var decPlaces = isNaN(decPlaces = Math.abs(decPlaces)) ? 2 : decPlaces,\r\n//vardecSep = typeof decSep === \"undefined\" ? \".\" : decSep;\r\n//var thouSep = typeof thouSep === \"undefined\" ? \",\" : thouSep;\r\n///var sign = number < 0 xss=removed xss=removed xss=removed xss=removed> 3 ? j % 3 : 0;\r\n\r\n//return sign +\r\n// (j ? i.substr(0, j) + thouSep : \"\") +\r\n// i.substr(j).replace(/(\\decSep{3})(?=\\decSep)/g, \"$1\" + thouSep) +\r\n// (decPlaces ? decSep + Math.abs(number - i).toFixed(decPlaces).slice(2) : \"\");\r\nreturn number;//.toFixed(2);//.replace(/\\d(?=(\\d{3})+\\.)/g, \'$&,\');\r\n}\r\n','','',9,'1617893664','1665017175'),(39,0,'tính khổ trải ngang hộp cứng','tinh_kho_trai_ngang_hop_cung(dai,rong, cao, kieu_hop,loai,trong_ngoai)','function tinh_kho_trai_ngang_hop_cung(dai,rong, cao, kieu_hop,loai,trong_ngoai) {\r\n\r\n  var kho_trai_ngang =0;\r\n    \r\n    //Hộp âm dương nắp 3.5cm-Áo C ngoài (nắp): Dài+3.5x2+4\r\n    if(kieu_hop == 30)\r\n    {\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_ngang=dai+3.5*3+4;\r\n       // Hộp âm dương nắp 3.5cm - Áo C (đáy): Dài-0.5+(cao-0.5)x2+(cao-1.5)x2\r\n    if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_ngang=dai-0.5+(cao-0.5)*2+(cao-1.5)*2;\r\n     \r\n     //Dài+3.5x2\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_ngang=dai+3.5*2;\r\n     \r\n     //Dài-0.5+(cao-0.5)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_ngang=dai-0.5+(cao-0.5)*2;\r\n     \r\n     //Dài+3.5x2\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_ngang=dai+(3-0.5)*2;\r\n     \r\n     //Dài+3.5x2\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_ngang=dai+-1;\r\n        \r\n    \r\n   }\r\n  \r\n    //Hộp âm dương nắp cao bằng đáy\r\n    if(kieu_hop == 31)\r\n    {\r\n        // Dài+(cao-1)x2+4\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_ngang=dai+(cao-1)*2+4;\r\n       // Dài-0.5+(cao-0.5)x2+(cao-1.5)x2\r\n      if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_ngang=dai-0.5+(cao-0.5)*2+(cao-1.5)*2;\r\n     \r\n     //Dài+(cao-1)x2\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_ngang=dai+(cao-1)*2;\r\n     \r\n     //Dài-0.5+(cao-0.5)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_ngang=dai-0.5+(cao-0.5)*2;\r\n     \r\n     //Dài+(cao-1)x2+4\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_ngang=dai+(cao-0.5)*2;\r\n     \r\n     //Dài+(cao-1)x2+4\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_ngang=dai-1;\r\n    \r\n   }\r\n   \r\n   //Hộp âm dương có thành\r\n   if(kieu_hop == 32)\r\n    {\r\n        //Dài+(2/3 cao)x2+4\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_ngang=dai+(2*cao/3)*2+4;\r\n       // Dài+(1/3 cao)x2+3\r\n      if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_ngang=dai+2*cao/3+3;\r\n     \r\n     //Dài+(2/3 cao)x2\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_ngang=dai+(2*cao/3)*2;\r\n     \r\n     // Dài+(1/3 cao)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_ngang=dai+2*cao/3;\r\n     \r\n     //Dài+(2/3 cao)x2-1\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_ngang=dai+(2*cao/3)*2 -1;\r\n      //Dài+(2/3 cao)x2-1\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_ngang=dai-1;\r\n     \r\n     \r\n     // Áo C (đáy trong)(thành): (Dài-0.5+rộng-0.5)x2+2\r\n      if (loai==\"thanh\" && trong_ngoai==\"ngoai\") kho_trai_ngang=(dai-0.5+rong-0.5)*2+2;\r\n      \r\n     //Carton đáy trong(thành): (Dài-0.5+rộng-0.5)x2\r\n     if (loai==\"thanh\" && trong_ngoai==\"trong\") kho_trai_ngang=(dai-0.5+rong-0.5)*2;\r\n     \r\n    \r\n   }\r\n    //Hộp nắp mở  nam châm\r\n    if(kieu_hop == 33| kieu_hop== 34)\r\n    {\r\n        // (Rộng+cao)x2+4\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_ngang=(rong+cao)*2+4;\r\n       // (Dài-0.5+rộng-0.5)x2+2\r\n      if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_ngang=(dai-0.5+rong-0.5)*2+2;\r\n     \r\n     //Carton nắp: (Rộng+cao)x2\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_ngang=(rong+cao)*2;\r\n     \r\n     //Carton đáy: Dài-0.5+(cao-0.5)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_ngang=dai-0.5+(cao-0.5)*2;\r\n     \r\n     //Lót C trong (nắp): Rộng+cao+2\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_ngang=rong+cao+2;\r\n     \r\n     //Dài-2\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_ngang=dai-1;\r\n    \r\n   }\r\n     //Hộp nắp mở bao diêm hở 2 đầu\r\n    if(kieu_hop == 35)\r\n    {\r\n       //Áo C ngoài (nắp): (Rộng+cao)x2+2\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_ngang=(rong+cao)*2+2;\r\n       // Áo C (đáy): Dài-0.5+(cao-0.5)x2+(cao-1.5)x2\r\n      if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_ngang=dai-0.5+(cao-0.5)*2+(cao-1.5)*2;\r\n     \r\n     //Carton nắp: (Rộng+cao)x2\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_ngang=(rong+cao)*2;\r\n     \r\n     //Carton đáy: Dài-0.5+(cao-0.5)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_ngang=dai-0.5+(cao-0.5)*2;\r\n     \r\n     //Lót C hoặc F trong (nắp): (Rộng+cao)x2-1\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_ngang=(rong+cao)*2-1;\r\n     \r\n     //Dài-2\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_ngang=dai-1;\r\n    \r\n   }\r\n  \r\n    //Hộp nắp mở bao diêm 1 đầu kín\r\n    if(kieu_hop == 36)\r\n    {\r\n       // Áo C ngoài (nắp): (Rộng+cao)x2+2\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_ngang=(rong+cao)*2+2;\r\n       // Áo C (đáy): Dài-0.5+(cao-0.5)x2+(cao-1.5)x2\r\n      if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_ngang=dai-0.5+(cao-0.5)*2+(cao-1.5)*2;\r\n     \r\n     //Carton nắp: (Rộng+cao)x2\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_ngang=(rong+cao)*2;\r\n     \r\n     //Carton đáy: Dài-0.5+(cao-0.5)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_ngang=dai-0.5+(cao-0.5)*2;\r\n     \r\n     //Lót C hoặc F trong (nắp): (Rộng+cao)x2-1\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_ngang=(rong+cao)*2-1;\r\n     \r\n     //Dài-2\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_ngang=dai-1;\r\n    \r\n   }\r\n   if (kho_trai_ngang>0.2) return kho_trai_ngang+0.2;\r\n     else return 0;\r\n      \r\n}','','',36,'1617938231','1618019412'),(40,0,'tính khổ trải cao hộp cứng','tinh_kho_trai_cao_hop_cung(dai,rong, cao, kieu_hop,loai,trong_ngoai)','function tinh_kho_trai_cao_hop_cung(dai,rong, cao, kieu_hop,loai,trong_ngoai) {\r\n\r\n   var kho_trai_cao =0;\r\n    \r\n    //Hộp âm dương nắp 3.5cm-Áo C ngoài (nắp): Dài+3.5x2+4\r\n    if(kieu_hop == 30)\r\n    {\r\n        //Áo C ngoài (nắp): Rộng+3.5x2+4\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_cao=rong+3.5*2+4;\r\n       // Áo C (đáy): Rộng-0.5+(cao-0.5)x2+(cao-1.5)x2\r\n    if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_cao=rong-0.5+(cao-0.5)*2+(cao-1.5)*2;\r\n     \