=\"trong\") kho_trai_cao=(rong+cao/3)*2;\r\n     \r\n     //Rộng+(2/3 cao)x2-1\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_cao=rong+(2*cao/3)*2 -1;\r\n     \r\n     //Dài+3.5x2\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_cao=rong-1;\r\n        \r\n    // Áo C (đáy trong): ((2/3 cao)-1)x2\r\n      if (loai==\"thanh\" && trong_ngoai==\"ngoai\") kho_trai_cao=((2*cao/3)-1)*2;\r\n      \r\n     //Carton đáy trong(thành): Carton đáy trong: (2/3 cao)\r\n     if (loai==\"thanh\" && trong_ngoai==\"trong\") kho_trai_cao=2*cao/3;\r\n   }\r\n     //Hộp nắp mở 1 nam châm\r\n    if(kieu_hop == 33||kieu_hop == 34)\r\n    {\r\n        //Áo C ngoài (nắp): dài+4\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_cao=dai+4;\r\n       //Áo C (đáy): (Cao-0.5)+(cao-1.5)+2\r\n      if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_cao=cao-0.5+(cao-1.5)*2;\r\n     \r\n     //Carton nắp: = dài\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_cao=dai;\r\n     \r\n     //Carton đáy: Rộng-0.5+(cao-0.5)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_cao=rong-0.5+(cao-0.5)*2;\r\n     \r\n     //Lót C trong (nắp): dài-1\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_cao=dai-1;\r\n     \r\n     //Dài+3.5x2\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_cao=rong-1;\r\n        \r\n    \r\n   }\r\n   //Hộp nắp mở bao diêm hở 2 đầu\r\n     if(kieu_hop == 35)\r\n    {\r\n        //Áo C ngoài (nắp): Dài+4\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_cao=dai+4;\r\n       //Áo C (đáy): Rộng-0.5+(cao-0.5)x2+(cao-1.5)x2\r\n      if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_cao=rong-0.5+(cao-0.5)*2+(cao-1.5)*2;\r\n     \r\n     //Carton nắp: = dài\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_cao=dai;\r\n     \r\n     //Carton đáy: Rộng-0.5+(cao-0.5)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_cao=rong-0.5+(cao-0.5)*2;\r\n     \r\n     //Lót C hoặc F trong (nắp): Dài-1\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_cao=dai-1;\r\n     \r\n     //Dài+3.5x2\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_cao=rong-1;\r\n        \r\n    \r\n   }\r\n   //Hộp nắp mở bao diêm 1 đầu kín\r\n      if(kieu_hop == 36)\r\n    {\r\n        //Áo C ngoài (nắp): Dài+cao+2\r\n      if (loai==\"nap\" && trong_ngoai==\"ngoai\") kho_trai_cao=dai+cao+2;\r\n       //Áo C (đáy): Rộng-0.5+(cao-0.5)x2+(cao-1.5)x2\r\n      if (loai==\"day\" && trong_ngoai==\"ngoai\") kho_trai_cao=rong-0.5+(cao-0.5)*2+(cao-1.5)*2;\r\n     \r\n     //Carton nắp: dài+cao\r\n     if (loai==\"nap\" && trong_ngoai==\"trong\") kho_trai_cao=dai+cao;\r\n     \r\n     //Carton đáy: Rộng-0.5+(cao-0.5)x2\r\n     if (loai==\"day\" && trong_ngoai==\"trong\") kho_trai_cao=rong-0.5+(cao-0.5)*2;\r\n     \r\n     //Lót C hoặc F trong (nắp): Dài+cao-1\r\n     if (loai==\"nap\" && trong_ngoai==\"lot\") kho_trai_cao=dai+cao-1;\r\n     \r\n     //Dài+3.5x2\r\n     if (loai==\"day\" && trong_ngoai==\"lot\") kho_trai_cao=rong-1;\r\n        \r\n    \r\n   }\r\n   if(kho_trai_cao>0.2) kho_trai_cao =kho_trai_cao+0.2;\r\n   else kho_trai_cao=0;\r\n     return kho_trai_cao;\r\n}','','',36,'1617938302','1618027313'),(41,0,'tính tiền mua giấy carton lạnh','tinh_tien_giay_carton_lanh(so_luong_cap,dinh_luong,rong,dai)','function tinh_tien_giay_carton_lanh(so_luong_cap,dinh_luong,rong,dai)\r\n{\r\n    var tien_mua_giay =0;\r\n    if(dinh_luong==0.8)tien_mua_giay=so_luong_cap*rong*dai*<Chip_board_800>;\r\n    if(dinh_luong==1.2)tien_mua_giay=so_luong_cap*rong*dai*<chip_board_1.2>;\r\n    if(dinh_luong==1.7)tien_mua_giay=so_luong_cap*rong*dai*<chip_board_1.7>;\r\n   if(dinh_luong==2)tien_mua_giay=so_luong_cap*rong*dai*<chip_board_2>;\r\n   if(dinh_luong==2.2)tien_mua_giay=so_luong_cap*rong*dai*<chip_board_2.2>;\r\n   if(dinh_luong==2.5)tien_mua_giay=so_luong_cap*rong*dai*<chip_board_2.5>;\r\n   if(dinh_luong==2.7)tien_mua_giay=so_luong_cap*rong*dai*<chip_board_2.7>;\r\n   if(dinh_luong==3)tien_mua_giay=so_luong_cap*rong*dai*<chip_board_3>;\r\n   if(dinh_luong==3.2)tien_mua_giay=so_luong_cap*rong*dai*<chip_board_3.2>;\r\n  \r\n     \r\n      return tien_mua_giay/10000;\r\n}','[\"770\",\"771\",\"772\",\"773\",\"942\",\"943\",\"944\",\"945\",\"774\"]','',34,'1618021761','1636626210'),(42,0,'tính tiền bế hộp cứng','tinh_tien_be_hop_cung(so_luong,kieu_hop)','function tinh_tien_be_hop_cung(so_luong,kieu_hop,cot_khay)\r\n{\r\n    var tien_be =0;\r\n    var tien_khuon_be =<gia_khuon_be>;\r\n    var tien_be_theo_lo=<gia_be_theo_lo>;\r\n    var tien_luot_be=<be_tu_dong>;\r\n    var tien_be_khay=0;\r\n    \r\n    if(cot_khay!=\"0\")\r\n    {\r\n         tien_be_khay=tien_luot_be*so_luong;\r\n         if(tien_be_khay<=tien_be_theo_lo) tien_be_khay=tien_be_theo_lo;\r\n         tien_be_khay=tien_be_khay+tien_khuon_be;\r\n        // alert(0);\r\n    }\r\n   \r\n    // âm dương\r\n    if(kieu_hop!=32)\r\n    {\r\n        var tien_be_ao_nap=tien_luot_be*so_luong;\r\n         if(tien_be_ao_nap<=tien_be_theo_lo) tien_be_ao_nap=tien_be_theo_lo;\r\n         \r\n        var tien_be_ao_day=tien_luot_be*so_luong;\r\n         if(tien_be_ao_day<=tien_be_theo_lo) tien_be_ao_day=tien_be_theo_lo;\r\n         \r\n        var tien_be_carton_nap=tien_luot_be*so_luong;\r\n         if(tien_be_carton_nap<=tien_be_theo_lo) tien_be_carton_nap=tien_be_theo_lo;\r\n         \r\n        var tien_be_carton_day=tien_luot_be*so_luong;\r\n         if(tien_be_carton_day<=tien_be_theo_lo) tien_be_carton_day=tien_be_theo_lo;\r\n         \r\n        tien_be =tien_be_ao_nap+tien_be_ao_day+tien_be_carton_nap+tien_be_carton_day+4*tien_khuon_be;\r\n   //alert(1);\r\n    }\r\n    //Hộp âm dương có thành\r\n      if(kieu_hop==32)\r\n    {\r\n        var tien_be_ao_nap=tien_luot_be*so_luong;\r\n         if(tien_be_ao_nap<=tien_be_theo_lo) tien_be_ao_nap=tien_be_theo_lo;\r\n         \r\n        var tien_be_ao_day=tien_luot_be*so_luong;\r\n         if(tien_be_ao_day<=tien_be_theo_lo) tien_be_ao_day=tien_be_theo_lo;\r\n         \r\n        var tien_be_carton_nap=tien_luot_be*so_luong;\r\n         if(tien_be_carton_nap<=tien_be_theo_lo) tien_be_carton_nap=tien_be_theo_lo;\r\n         \r\n        var tien_be_carton_day=tien_luot_be*so_luong;\r\n         if(tien_be_carton_day<=tien_be_theo_lo) tien_be_carton_day=tien_be_theo_lo;\r\n         \r\n         var tien_be_carton_day=tien_luot_be*so_luong;\r\n         if(tien_be_carton_day<=tien_be_theo_lo) tien_be_carton_day=tien_be_theo_lo;\r\n         \r\n        var tien_be_carton_thanh=tien_luot_be*so_luong;\r\n         if(tien_be_carton_day<=tien_be_theo_lo) tien_be_carton_thanh=tien_be_theo_lo;\r\n       \r\n        tien_be =tien_be_carton_thanh+tien_be_ao_nap+tien_be_ao_day+tien_be_carton_nap+tien_be_carton_day+5*tien_khuon_be;\r\n  // alert(2);\r\n    }\r\n   \r\n     //alert(3);\r\n    return  tien_be+tien_be_khay;\r\n}','[\"927\",\"928\",\"835\"]','',37,'1618038386','1618244572'),(43,0,'tính tiền bồi hộp cứng','tinh_tien_boi_hop_cung(so_luong,kieu_hop)','function tinh_tien_boi_hop_cung(so_luong,kieu_hop)\r\n{\r\n    var tien_boi=0;\r\n    var tien_khuon_thut_boi=<khuon_thut_boi>;\r\n    var tien_boi_ao_hop_cung=<tien_boi_ao_hop_cung>;\r\n    var tien_boi_bia_nho= <tien_boi_bia_nho>;\r\n    var tien_boi_bia_lon=<tien_boi_bia_lon>\r\n    // âm dương\r\n    if(kieu_hop=30||kieu_hop==31)\r\n    {\r\n       tien_boi =(tien_boi_ao_hop_cung*so_luong+tien_khuon_thut_boi)*2;\r\n         \r\n    }\r\n    //Hộp âm dương có thành\r\n      if(kieu_hop==32)\r\n    {\r\n        // tiền bồi nắp+ tiền bồi đáy + tiền bồi thành\r\n        tien_boi =(tien_boi_ao_hop_cung*so_luong+tien_khuon_thut_boi)*2+tien_boi_bia_nho*so_luong;  \r\n    }\r\n    // hộp nam châm\r\n     if(kieu_hop==33||kieu_hop==34)\r\n    {\r\n        // tiền bồi nắp+ tiền bồi đáy + tiền bồi thành\r\n        tien_boi =tien_boi_ao_hop_cung*so_luong+tien_khuon_thut_boi+tien_boi_bia_lon*so_luong;  \r\n    }\r\n      if(kieu_hop=35||kieu_hop==36)\r\n    {\r\n       tien_boi =tien_boi_ao_hop_cung*so_luong+tien_khuon_thut_boi+tien_boi_bia_lon*so_luong; \r\n         \r\n    }\r\n    return  tien_boi;\r\n}','[\"946\",\"947\",\"948\",\"949\"]','',35,'1618039835','1618042692'),(44,0,'Tính tiền phay hộp cứng',' tinh_tien_phay(so_luong,kieu_hop)','function tinh_tien_phay(so_luong,kieu_hop)\r\n{\r\n    var tong_tien_phay=0;\r\n    var tien_phay_lo=<tien_phay_tren_lo>;\r\n    var gia_phay_mot_ranh=<gia_phay_mot_ranh>;\r\n    var tong_so_duong_phay=0;\r\n    // hộp âm dương\r\n    if(kieu_hop==30||kieu_hop==31)\r\n    {\r\n      var so_duong_phay_nap=4;\r\n      \r\n      var so_duong_phay_day=4;\r\n      \r\n      tong_so_duong_phay=so_duong_phay_nap+so_duong_phay_day;\r\n      \r\n      tong_tien_phay=so_luong*tong_so_duong_phay*gia_phay_mot_ranh;\r\n      \r\n      if(tong_tien_phay<=tien_phay_lo)tong_tien_phay=tien_phay_lo;\r\n      \r\n        \r\n    }\r\n    // hộp âm dương có thành\r\n     if(kieu_hop==32)\r\n    {\r\n      var so_duong_phay_nap=4;\r\n      \r\n      var so_duong_phay_day=4;\r\n         var so_duong_phay_thanh=4;\r\n      \r\n      tong_so_duong_phay=so_duong_phay_nap+so_duong_phay_day+so_duong_phay_thanh;\r\n      \r\n      tong_tien_phay=so_luong*tong_so_duong_phay*gia_phay_mot_ranh;\r\n      \r\n      if(tong_tien_phay<=tien_phay_lo)tong_tien_phay=tien_phay_lo;\r\n      \r\n        \r\n    }\r\n      if(kieu_hop==33||kieu_hop==34)\r\n    {\r\n      var so_duong_phay_nap=3;\r\n      \r\n       var so_duong_phay_day=4;\r\n        // var so_duong_phay_thanh=4;\r\n      \r\n      tong_so_duong_phay=so_duong_phay_nap+so_duong_phay_day;\r\n      \r\n      tong_tien_phay=so_luong*tong_so_duong_phay*gia_phay_mot_ranh;\r\n      \r\n      if(tong_tien_phay<=tien_phay_lo)tong_tien_phay=tien_phay_lo;\r\n      \r\n        \r\n    }\r\n      // hộp bao diem 2 đầu hở \r\n       if(kieu_hop==35)\r\n    {\r\n      var so_duong_phay_nap=3;\r\n      \r\n       var so_duong_phay_day=4;\r\n        // var so_duong_phay_thanh=4;\r\n      \r\n      tong_so_duong_phay=so_duong_phay_nap+so_duong_phay_day;\r\n      \r\n      tong_tien_phay=so_luong*tong_so_duong_phay*gia_phay_mot_ranh;\r\n      \r\n      if(tong_tien_phay<=tien_phay_lo)tong_tien_phay=tien_phay_lo;\r\n      \r\n        \r\n    }\r\n    // hộp bao diem 1 dầu kính \r\n       if(kieu_hop==36)\r\n    {\r\n      var so_duong_phay_nap=4;\r\n      \r\n       var so_duong_phay_day=4;\r\n        // var so_duong_phay_thanh=4;\r\n      \r\n      tong_so_duong_phay=so_duong_phay_nap+so_duong_phay_day;\r\n      \r\n      tong_tien_phay=so_luong*tong_so_duong_phay*gia_phay_mot_ranh;\r\n      \r\n      if(tong_tien_phay<=tien_phay_lo)tong_tien_phay=tien_phay_lo;\r\n      \r\n        \r\n    }\r\n    return tong_tien_phay;\r\n    \r\n}','[\"950\",\"951\"]','',35,'1618042934','1618044254'),(45,0,'tính khổ trải ngang của khay ','tinh_kho_trai_ngang_khay(dai,rong,cao,cot_khay)','function tinh_kho_trai_ngang_khay(dai,rong,cao,cot_khay)\r\n{\r\n    var kho_trai_ngang=0;\r\n    if(cot_khay==0) return 0;\r\n    //Khay giấy Ivory 400gsm Dài-1+2.5\r\n      if(cot_khay==1||cot_khay==1.2||cot_khay==1.7||cot_khay==2||cot_khay==2.2||cot_khay==2.7||cot_khay==3||cot_khay==3.2) kho_trai_ngang=dai-1+2.5;\r\n      else kho_trai_ngang= dai-1;\r\n      return kho_trai_ngang;\r\n    \r\n}','','',36,'1618131530','1618132758'),(46,0,'tính khổ trải cao của khay','tinh_kho_trai_cao_khay(dai,rong,cao,cot_khay)','function tinh_kho_trai_cao_khay(dai,rong,cao,cot_khay)\r\n{\r\n    var kho_trai_cao=0;\r\n    if(cot_khay==0) return 0;\r\n    //Khay giấy Ivory 400gsm Dài-1+2.5\r\n      if(cot_khay==1||cot_khay==1.2||cot_khay==1.7||cot_khay==2||cot_khay==2.2||cot_khay==2.7||cot_khay==3||cot_khay==3.2) kho_trai_cao=rong-1+2.5;\r\n      else   kho_trai_cao= rong-1;\r\n      \r\n    \r\n      return kho_trai_cao;\r\n    \r\n}','','',36,'1618132319','1618132683'),(47,0,'tính tiền carton khay','tinh_tien_khay_carton(so_luong_cap,cot_khay,rong,dai)','function tinh_tien_khay_carton(so_luong_cap,cot_khay,rong,dai)\r\n{\r\n    var tien_mua_giay=0;\r\n    if(cot_khay==0) return 0;\r\n    if(cot_khay==1.2)tien_mua_giay=tien_khay=tinh_tien_giay_carton_lanh(so_luong_cap,cot_khay,rong,dai); \r\n    if(cot_khay==1.7)tien_mua_giay=tien_khay=tinh_tien_giay_carton_lanh(so_luong_cap,cot_khay,rong,dai); \r\n    if(cot_khay==2)tien_mua_giay=tien_khay=tinh_tien_giay_carton_lanh(so_luong_cap,cot_khay,rong,dai); \r\n    if(cot_khay==2.2)tien_mua_giay=tien_khay=tinh_tien_giay_carton_lanh(so_luong_cap,cot_khay,rong,dai); \r\n      if(cot_khay==2.5)tien_mua_giay=tien_khay=tinh_tien_giay_carton_lanh(so_luong_cap,cot_khay,rong,dai); \r\n      if(cot_khay==2.7)tien_mua_giay=tien_khay=tinh_tien_giay_carton_lanh(so_luong_cap,cot_khay,rong,dai); \r\n      if(cot_khay==3)tien_mua_giay=tien_khay=tinh_tien_giay_carton_lanh(so_luong_cap,cot_khay,rong,dai); \r\n   if(cot_khay==3.2)tien_mua_giay=tien_khay=tinh_tien_giay_carton_lanh(so_luong_cap,cot_khay,rong,dai); \r\n    return   tien_mua_giay    ;                                   \r\n}','','[\"41\"]',34,'1618240978','1618244095'),(48,0,'tính tiền mút khay',' tinh_tien_khay_mut(so_to_cap_khay_mut,cot_khay,chieu_rong_mut,chieu_dai_mut)','function tinh_tien_khay_mut(so_to_cap_khay_mut,cot_khay,chieu_rong_mut,chieu_dai_mut)\r\n{\r\n    var tien_mut =0;\r\n   // alert(cot_khay);\r\n   //chieu_rong_mut =chieu_rong_mut/100;\r\n   //chieu_dai_mut=chieu_dai_mut/100;\r\n    if(cot_khay==0)return 0;\r\n   \r\n     //chieu_rong_mut\r\n    if(cot_khay==\"md1\") tien_mut=so_to_cap_khay_mut*chieu_rong_mut*chieu_dai_mut*<mut_den_1_cm>;\r\n   \r\n    if(cot_khay==\"md2\") tien_mut=so_to_cap_khay_mut*chieu_rong_mut*chieu_dai_mut*<mut_den_2_cm>;\r\n    if(cot_khay==\"md3\") tien_mut=so_to_cap_khay_mut*chieu_rong_mut*chieu_dai_mut*<mut_den_3_cm>;\r\n    if(cot_khay==\"md4\") tien_mut=so_to_cap_khay_mut*chieu_rong_mut*chieu_dai_mut*<mut_den_4_cm>;\r\n    if(cot_khay==\"mt1\") tien_mut=so_to_cap_khay_mut*chieu_rong_mut*chieu_dai_mut*<mut_trang_1_cm>;\r\n    if(cot_khay==\"mt2\") tien_mut=so_to_cap_khay_mut*chieu_rong_mut*chieu_dai_mut*<mut_trang_2_cm>;\r\n    if(cot_khay==\"mt3\") tien_mut=so_to_cap_khay_mut*chieu_rong_mut*chieu_dai_mut*<mut_trang_3_cm>;\r\n    if(cot_khay==\"mt4\") tien_mut=so_to_cap_khay_mut*chieu_rong_mut*chieu_dai_mut*<mut_trang_4_cm>;\r\n    return tien_mut/10000;\r\n}','[\"953\",\"954\",\"963\",\"956\",\"957\",\"958\",\"960\",\"959\"]','',35,'1618241975','1642150458'),(49,0,'Tiền tiền bồi khay','tinh_tien_boi_khay(so_luong,kho_trai_ngang_khay,kho_trai_cao_khay,boi_khay)','function tinh_tien_boi_khay(so_luong,kho_trai_ngang_khay,kho_trai_cao_khay,boi_khay)\r\n{\r\n    var tien_boi_khay =0;\r\n    // var tien_van_chuyen_giay= <tien_van_chuyen_giay>;\r\n      // var tien_cat_giay=<cat_giay>;\r\n    //      Không bồi khay   \r\n      if(boi_khay==\"0\") return 0;\r\n      // bồi C - tính trên khố 65x86 cho nó tiện chứ mệt quá cmnr\r\n    if(boi_khay==1)\r\n    {\r\n        var dien_tien_sp=kho_trai_ngang_khay*kho_trai_cao_khay;\r\n       var so_luong_sp_tren_to =Math.floor(65*86/dien_tien_sp);\r\n       // alert (so_luong_sp_tren_to);\r\n        var so_luong_cap =Math.ceil(so_luong/so_luong_sp_tren_to);\r\n   //  alert (so_luong_cap);\r\n        tien_boi_khay=  <tien_cong_boi_tren_lo>+ tinh_tien_giay(so_luong_cap,\"C\",150,65,86);\r\n    }\r\n    //bôi nhung đen đỏ\r\n    if(boi_khay ==2)\r\n    {\r\n       tien_boi_khay=  <tien_cong_boi_tren_lo>+ (so_luong*kho_trai_ngang_khay*kho_trai_cao_khay*<tien_nhung_den>)/10000;\r\n    }\r\n    // bồi nhung trắng\r\n     if(boi_khay ==3)\r\n     {\r\n         tien_boi_khay= <tien_cong_boi_tren_lo>+( so_luong*kho_trai_ngang_khay*kho_trai_cao_khay*<tien_nhung_trang>)/10000;\r\n     }\r\n     // lụa thường \r\n      if(boi_khay ==4)tien_boi_khay =so_luong*<lua_thuong>;\r\n     // lụa cao cấp\r\n      if(boi_khay ==5)tien_boi_khay =so_luong*<lua_cao_cap>;\r\n      return tien_boi_khay;\r\n}','[\"961\",\"962\",\"964\",\"952\",\"660\",\"662\",\"932\"]','[\"18\"]',35,'1618245227','1618247256'),(50,0,'Tính tiền carton bồi','tinh_tien_carton_boi(so_luong,kho_trai_ngang,kho_trai_cao,boi_giay)','function tinh_tien_carton_boi(so_luong,kho_trai_ngang,kho_trai_cao,boi_giay){\r\n    var tien_mua_giay=0;\r\n  //Sóng A 2 lớp\r\n     if(boi_giay==2)   tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng A 2 lớp>)/10000;\r\n     //Sóng AB\r\n      if(boi_giay==3)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng AB>)/10000;\r\n        //Sóng B\r\n      if(boi_giay==4)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng B>)/10000;\r\n      //Sóng B 2 lớp\r\n   if(boi_giay==5)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng B 2 lớp> )/10000;\r\n    //Sóng BE\r\n     if(boi_giay==6)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng BE> )/10000;\r\n     //Sóng E\r\n     if(boi_giay==7)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng E> )/10000;\r\n    //Sóng E 2 lớp\r\n     if(boi_giay==8)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng E 2 lớp> )/10000;\r\n    //Sóng E 2 xeo\r\n     if(boi_giay==9)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng E 2 xeo>  )/10000;\r\n    //Sóng E 3 lớp\r\n     if(boi_giay==10)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng E 3 lớp>  )/10000;\r\n\r\n   //Sóng EB chống thấm\r\n     if(boi_giay==11)  tien_mua_giay =(so_luong*kho_trai_ngang*kho_trai_cao*<Sóng EB chống thấm>   )/10000;\r\n    return tien_mua_giay;\r\n}','[\"778\",\"779\",\"782\",\"783\",\"784\",\"787\",\"786\",\"785\",\"780\",\"781\"]','',35,'1633492502','1633493225'),(51,0,'Lấy số lượng tờ cấp hộp cứng','lay_so_luong_to_cap_hop_cung','function lay_so_luong_to_cap_hop_cung(so_luong,so_luong_sp_tren_to_nap,bu_hao_nap,so_luong_sp_tren_to_day,bu_hao_day)\r\n{\r\n    var so_luong_to_cap =0;\r\n\r\n    if(so_luong_sp_tren_to_nap==0|| so_luong_sp_tren_to_day==0) so_luong_to_cap ==0;\r\n    else if(so_luong_sp_tren_to_nap!=0 &&so_luong_sp_tren_to_day!=0 )\r\n    {\r\n        so_luong_to_cap = Math.ceil(so_luong/so_luong_sp_tren_to_nap) + bu_hao_nap +Math.ceil(so_luong/so_luong_sp_tren_to_day)+bu_hao_day;\r\n    }\r\n return   so_luong_to_cap;\r\n \r\n    \r\n}','','[\"16\"]',36,'1636620623','1636623632'),(52,0,'Tinh Tổng Tiền Mua Giấy','tinh_tong_tien_mua_giay','function tinh_tong_tien_mua_giay(tien_giay_ao,tien_giay_thanh,tien_giay_lot)\r\n{\r\n    var tong_tien =0;\r\n    if(tien_giay_ao==0)tong_tien =0;\r\n    else if (tien_giay_ao!=0)tong_tien = tien_giay_ao+tien_giay_thanh+tien_giay_lot;\r\n    return tong_tien;\r\n}','','',34,'1636691386','1636691386'),(53,0,'Tính tiền gia công hộp cứng','tinh_tien_gia_cong_hop_cung(so_luong,kieu_hop,dai,rong,cao)','function tinh_tien_gia_cong_hop_cung(so_luong,kieu_hop,dai,rong,cao)\r\n{\r\n    var tien_boi=0;\r\n    var tien_khuon_thut_boi=<khuon_thut_boi>;\r\n    var tien_boi_ao_hop_cung=<tien_boi_ao_hop_cung>;\r\n    var tien_boi_bia_nho= <tien_boi_bia_nho>;\r\n    var tien_boi_bia_lon=<tien_boi_bia_lon>\r\n    // âm dương\r\n    if(kieu_hop=30||kieu_hop==31)\r\n    {\r\n       tien_boi =(tien_boi_ao_hop_cung*so_luong+tien_khuon_thut_boi)*2;\r\n         \r\n    }\r\n    //Hộp âm dương có thành\r\n      if(kieu_hop==32)\r\n    {\r\n        // tiền bồi nắp+ tiền bồi đáy + tiền bồi thành\r\n        tien_boi =(tien_boi_ao_hop_cung*so_luong+tien_khuon_thut_boi)*2+tien_boi_bia_nho*so_luong;  \r\n    }\r\n    // hộp nam châm\r\n     if(kieu_hop==33||kieu_hop==34)\r\n    {\r\n        // tiền bồi nắp+ tiền bồi đáy + tiền bồi thành\r\n        tien_boi =tien_boi_ao_hop_cung*so_luong+tien_khuon_thut_boi+tien_boi_bia_lon*so_luong;  \r\n    }\r\n      if(kieu_hop=35||kieu_hop==36)\r\n    {\r\n       tien_boi =tien_boi_ao_hop_cung*so_luong+tien_khuon_thut_boi+tien_boi_bia_lon*so_luong; \r\n         \r\n    }\r\n    return  tien_boi;\r\n}','[\"946\",\"947\",\"948\",\"949\"]','',35,'1636706205','1636706903'),(54,0,'Lấy giá cuối cùng của sản phẩm','lay_gia_cuoi_cung_san_pham','function lay_gia_cuoi_cung_san_pham(gia_kho_lo,gia_kho_65_86,gia_kho_79_109)\r\n{\r\n    var gia_cuoi_cung=0;\r\n    if(gia_kho_lo!=0 && gia_kho_65_86!=0 && gia_kho_79_109!=0 )\r\n    {\r\n       gia_cuoi_cung= MinThreeNum(gia_kho_lo,gia_kho_65_86,gia_kho_79_109)\r\n    }\r\n    if(gia_kho_lo==0 && gia_kho_65_86!=0 && gia_kho_79_109!=0)\r\n    {\r\n        gia_cuoi_cung= MinTwoNum(gia_kho_65_86,gia_kho_79_109)\r\n    }\r\n    if(gia_kho_lo==0 && gia_kho_65_86==0 && gia_kho_79_109!=0)\r\n    {\r\n        gia_cuoi_cung= gia_kho_79_109;\r\n    }\r\n    if(gia_kho_lo!=0 && gia_kho_65_86==0 && gia_kho_79_109!=0)\r\n    {\r\n        gia_cuoi_cung= MinTwoNum(gia_kho_lo,gia_kho_79_109)\r\n    }\r\n    \r\n    if(gia_kho_lo!=0 && gia_kho_65_86!=0 && gia_kho_79_109==0)\r\n    {\r\n        gia_cuoi_cung= MinTwoNum(gia_kho_lo,gia_kho_65_86)\r\n    }\r\n      if(gia_kho_lo!=0 && gia_kho_65_86==0 && gia_kho_79_109==0)\r\n    {\r\n        gia_cuoi_cung=gia_kho_lo;\r\n    }\r\n    \r\n      if(gia_kho_lo==0 && gia_kho_65_86!=0 && gia_kho_79_109==0)\r\n    {\r\n        gia_cuoi_cung=gia_kho_65_86;\r\n    }\r\n    return gia_cuoi_cung ;\r\n    \r\n}','','[\"12\",\"10\"]',37,'1636794621','1636794907'),(55,0,'Tính tiền túi giấy','tinh_tien_tui_giay(so_luong)','function tinh_tien_tui_giay(so_luong)\r\n{\r\n    var tong_tien=0;\r\n    if(so_luong<=10) tong_tien=so_luong*25000;\r\n    if(so_luong>10 && so_luong<=20)tong_tien=so_luong*20000;\r\n     if(so_luong>20 && so_luong<=30)tong_tien=so_luong*18000;\r\n     if(so_luong>30 && so_luong<=50)tong_tien=so_luong*17000;\r\n     if(so_luong>50 && so_luong<=200)tong_tien=so_luong*15000;\r\n     if(so_luong>200 && so_luong<=500)tong_tien=so_luong*13000;\r\n     if(so_luong>500 && so_luong<=1000)tong_tien=so_luong*12000;\r\n     if(so_luong>1000 && so_luong<=2000)tong_tien=so_luong*11000;\r\n     if(so_luong>2000)tong_tien=so_luong*10000;\r\n     return tong_tien;\r\n}','','',37,'1637035444','1637035747'),(56,0,'Tính số sản phẩm trên tờ','lay_so_sp_tren_to(kho_trai_ngang,kho_trai_cao,kieu_hop,rong_kho_giay,dai_kho_giay)','function lay_so_sp_tren_to(kho_trai_ngang,kho_trai_cao,kieu_hop,rong_kho_giay,dai_kho_giay){\r\n      \r\n    \r\n     var kho_trai_cao_2_sp =kho_trai_cao*2;\r\n     var kho_trai_cao_3_sp =kho_trai_cao*3;\r\n    \r\n     //return kho_trai_cao;\r\n    \r\n     // kiểu ghép hộp ngang\r\n     var tong_sp_ghep_ngang=0;\r\n     var so_sp_xep_ngang_ghep_ngang=0;\r\n     var so_sp_xep_doc_ghep_ngang=0;\r\n     tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n     \r\n      // kiểu ghép hộp dọc\r\n     var tong_sp_ghep_doc=0;\r\n     var so_sp_xep_ngang_ghep_doc=0;\r\n     var so_sp_xep_doc_ghep_doc=0;\r\n     tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n     // số lượng sản trên tờ \r\n       \r\n     // nếu kiểu hộp rơi vào Hộp dán hông đáy xếp, 1 khóa gài hoặc Hộp dán hông 2 khóa cài (RTE)\r\n     \r\n     // kiểu ghép hộp ngang 2 sp\r\n     var tong_sp_ghep_ngang_2p=0;\r\n     var so_sp_xep_ngang_ghep_ngang_2p=0;\r\n     var so_sp_xep_doc_ghep_ngang_2p=0;\r\n     tong_sp_ghep_ngang_2p=so_sp_xep_ngang_ghep_ngang_2p*so_sp_xep_doc_ghep_ngang_2p;\r\n     \r\n      // kiểu ghép hộp dọc 2p\r\n     var tong_sp_ghep_doc_2p=0;\r\n     var so_sp_xep_ngang_ghep_doc_2p=0;\r\n     var so_sp_xep_doc_ghep_doc_2p=0;\r\n     tong_sp_ghep_doc_2p=so_sp_xep_ngang_ghep_doc_2p*so_sp_xep_doc_ghep_doc_2p;\r\n     // số lượng sản trên tờ \r\n    \r\n     var max_sp_ghep =0;\r\n    \r\n     // trường hợp 4,5 phải cộng 1.2cm\r\n    \r\n     var tong_sp_ghep_3=0;\r\n     \r\n   \r\n     \r\n       // trường hợp ghép ngang không an gian giấy\r\n \r\n          so_sp_xep_ngang_ghep_ngang=Math.floor(dai_kho_giay/kho_trai_cao);\r\n         // return so_sp_xep_ngang;  \r\n          so_sp_xep_doc_ghep_ngang=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          \r\n          tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n          \r\n       // trường hợp ghép dọc\r\n   \r\n        so_sp_xep_ngang_ghep_doc=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n         \r\n        so_sp_xep_doc_ghep_doc=Math.floor(rong_kho_giay/kho_trai_cao);\r\n        \r\n        tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n        \r\n      \r\n      var tong = 0;\r\n        tong =MaxThreeNum( MaxTwoNum(tong_sp_ghep_ngang_2p,tong_sp_ghep_doc_2p),tong_sp_ghep_3,MaxTwoNum(tong_sp_ghep_ngang,tong_sp_ghep_doc));\r\n      if(tong==0) tong =1;\r\n      return tong;\r\n      //return MaxThreeNum( MaxTwoNum(tong_sp_ghep_ngang_2p,tong_sp_ghep_doc_2p),tong_sp_ghep_3,MaxTwoNum(tong_sp_ghep_ngang,tong_sp_ghep_doc));\r\n}   ','','[\"13\",\"11\"]',36,'1637138643','1677555455'),(57,0,'Lấy số chia khổ trải','lay_so_chia_kho_trai(kho_trai,kich_thuoc)','function lay_so_chia_kho_trai(kho_trai,kich_thuoc)\r\n{\r\n    var so_chia =1;\r\n    //var v_kho_trai =kho_trai;\r\n   // for (var i= 0; i <100;i++)\r\n   // {\r\n   // if(v_kho_trai>kich_thuoc)\r\n   //    {\r\n   //        so_chia =i+1;\r\n   //        v_kho_trai=v_kho_trai/so_chia;\r\n           //so_chia=v_kho_trai/(i+1);\r\n   //    }\r\n   // }\r\n       if(kho_trai>=kich_thuoc)\r\n       so_chia= Math.ceil(kho_trai/kich_thuoc,0);\r\n       return so_chia;\r\n   \r\n}','','',36,'1637140851','1637142117'),(58,0,'Lấy số lượng tờ cấp','lay_so_luong_to_cap','function lay_so_luong_to_cap(so_luong,so_luong_sp_tren_to,bu_hao_nap)\r\n{\r\n    var so_luong_to_cap =0;\r\n\r\n    if(so_luong_sp_tren_to==0) so_luong_to_cap ==0;\r\n    else if(so_luong_sp_tren_to!=0)\r\n    {\r\n        so_luong_to_cap = Math.ceil(so_luong/so_luong_sp_tren_to) + bu_hao_nap ;\r\n    }\r\n return   so_luong_to_cap;\r\n \r\n    \r\n}','','',36,'1637315278','1637316246'),(59,0,'Lấy chiều dài chiều rộng khổ giấy','lay_kho_giay(kho_giay)','function lay_kho_giay(kho_giay)\r\n{\r\n    var d=86;\r\n    var r=65\r\n    try {\r\n       d=kho_giay.split(\'x\')[1];\r\n       r=kho_giay.split(\'x\')[0];\r\n    }\r\n    catch(err) \r\n    {\r\n        //message[removed] = \"Input is \" + err;\r\n        r=65\r\n        d=86;\r\n    }\r\n    var obj = new Object();\r\n    obj.rong=parseFloat(r);\r\n    obj.dai=parseFloat(d);\r\n   return obj;\r\n}','','',9,'1665284411','1665286843'),(60,0,'tính tính hộp quà tết 2023','tinh_hop_qua_tet_2023(so_luong)','function tinh_hop_qua_tet_2023(so_luong)\r\n{\r\n    var tong_tien=0;\r\n    if(so_luong<=10) tong_tien=so_luong*45000;\r\n    if(so_luong>10 && so_luong<=20)tong_tien=so_luong*43000;\r\n     if(so_luong>20 && so_luong<=50)tong_tien=so_luong*40000;\r\n     if(so_luong>50 && so_luong<=100)tong_tien=so_luong*38000;\r\n     if(so_luong>100 && so_luong<=300)tong_tien=so_luong*37000;\r\n     if(so_luong>300 && so_luong<=500)tong_tien=so_luong*36000;\r\n     if(so_luong>500 && so_luong<=1000)tong_tien=so_luong*34000;\r\n     if(so_luong>1000 && so_luong<=2000)tong_tien=so_luong*33000;\r\n     if(so_luong>2000 && so_luong<=5000)tong_tien=so_luong*32000;\r\n     if(so_luong>5000 && so_luong<10000)tong_tien=so_luong*31000;\r\n   if(so_luong>=10000 )tong_tien=so_luong*30000;\r\n     return tong_tien;\r\n}','','',9,'1665809706','1665809795'),(61,0,'Tính giá hộp quà tết theo số lượng','tinh_gia_theo_so_luong_hop_qua_tet_2023(so_luong)','function gia_hop_tet_2023(so_luong)\r\n{\r\n    var tong_tien=0;\r\n    if(so_luong&lt;=10) tong_tien=45000;\r\n    if(so_luong>10 && so_luong&lt;=20)tong_tien=43000;\r\n     if(so_luong>20 && so_luong&lt;=50)tong_tien=40000;\r\n     if(so_luong>50 && so_luong&lt;=100)tong_tien=38000;\r\n     if(so_luong>100 && so_luong&lt;=300)tong_tien=37000;\r\n     if(so_luong>300 && so_luong&lt;=500)tong_tien=36000;\r\n     if(so_luong>500 && so_luong&lt;=1000)tong_tien=34000;\r\n     if(so_luong>1000 && so_luong&lt;=2000)tong_tien=33000;\r\n     if(so_luong>2000 && so_luong&lt;=5000)tong_tien=32000;\r\n     if(so_luong>5000 && so_luong<10000 tong_tien=31000;>=10000 )tong_tien=30000;\r\n     return tong_tien;\r\n}','','',9,'1665810064','1665810064'),(62,0,'tính giá theo số lượng hộp quà tết 2023','tinh_hop_tet_2023(so_luong)','function tinh_hop_tet_2023(so_luong)\r\n{\r\n    var tong_tien=0;\r\n    if(10>=so_luong && so_luong<20 ) tong_tien=45000;\r\n\r\n     if(so_luong>=20 && so_luong<50)tong_tien=43000;\r\n\r\n     if(so_luong>=50 && so_luong<100)tong_tien=40000;\r\n\r\n     if(so_luong>=100 && so_luong<300)tong_tien=38000;\r\n\r\n     if(so_luong>=300 && so_luong<500)tong_tien=37000;\r\n\r\n     if(so_luong>=500 && so_luong<1000)tong_tien=36000;\r\n\r\n     if(so_luong>=1000 && so_luong<2000)tong_tien=34000;\r\n\r\n     if(so_luong>=2000 && so_luong<5000)tong_tien=33000;\r\n\r\n     if(so_luong>=5000 && so_luong<10000)tong_tien=32000;\r\n\r\n     if(so_luong>=10000 )tong_tien=30000;\r\n     return tong_tien;\r\n}','','',9,'1665810137','1665813808'),(63,0,'Tính tiền hộp quà tết cao cấp 2023','tinh_hop_cao_cap_tet_2023(so_luong)','function tinh_hop_cao_cap_tet_2023(so_luong)\r\n{\r\n    var tong_tien=0;\r\n    if(10>=so_luong && so_luong<20) tong_tien=70000;\r\n   if(so_luong>=20 && so_luong<30) tong_tien=60000;\r\n   if(so_luong>=30 && so_luong<50) tong_tien=59000;\r\nif(so_luong>=50 && so_luong<100) tong_tien=54000;\r\nif(so_luong>=100 && so_luong<500) tong_tien=52000;\r\nif(so_luong>=500 && so_luong<1000) tong_tien=49000;\r\nif(so_luong>=1000 && so_luong<2000) tong_tien=47000;\r\nif(so_luong>=2000 && so_luong<5000) tong_tien=45000;\r\nif(so_luong>=5000 && so_luong<10000) tong_tien=43000;\r\nif(so_luong>=10000)tong_tien=40000;\r\n     return tong_tien;\r\n}','','',9,'1666759575','1666759936'),(64,0,' Kiểm tra túi này có phải nối hay không?','kiem_tra_tui_noi(kho_trai_ngang)','function kiem_tra_tui_noi(kho_trai_ngang)\r\n{\r\n    var kq=0;\r\n    // nếu kq =0 thì không nối \r\n    // nếu kq =1 thì phải nối\r\n    var chieu_dai_phai_noi=<chieu_ngang_lam_tui_noi>;\r\n    if(kho_trai_ngang>chieu_dai_phai_noi)\r\n    kq=1;\r\n    else kq=0;\r\n    return kq;\r\n    \r\n}','[\"992\"]','',9,'1677223997','1677224079'),(65,0,'Tính sản phẩm trên tờ cho túi giấy ','lay_so_sp_tren_to_tui_giay(kho_trai_ngang,kho_trai_cao,rong_kho_giay,dai_kho_giay)','function lay_so_sp_tren_to_tui_giay(ktn,ktc,rong_kho_giay,dai_kho_giay)\r\n{\r\n    \r\n    \r\n     var kho_trai_cao=ktc;\r\n     var kho_trai_ngang=ktn;\r\n     //return kho_trai_cao;\r\n    \r\n     // kiểu ghép hộp ngang\r\n     var tong_sp_ghep_ngang=0;\r\n     var so_sp_xep_ngang_ghep_ngang=0;\r\n     var so_sp_xep_doc_ghep_ngang=0;\r\n     tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n     \r\n      // kiểu ghép hộp dọc\r\n     var tong_sp_ghep_doc=0;\r\n     var so_sp_xep_ngang_ghep_doc=0;\r\n     var so_sp_xep_doc_ghep_doc=0;\r\n     tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n     \r\n     \r\n     // số lượng sản trên tờ \r\n    \r\n          // trường hợp ghép ngang không an gian giấy\r\n \r\n          so_sp_xep_ngang_ghep_ngang=Math.floor(dai_kho_giay/kho_trai_cao);\r\n         // return so_sp_xep_ngang;  \r\n          so_sp_xep_doc_ghep_ngang=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          \r\n          tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n          \r\n       // trường hợp ghép dọc\r\n   \r\n        so_sp_xep_ngang_ghep_doc=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n         \r\n        so_sp_xep_doc_ghep_doc=Math.floor(rong_kho_giay/kho_trai_cao);\r\n        \r\n        tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n        \r\n        var tong=0;\r\n        tong=  MaxTwoNum(tong_sp_ghep_ngang,tong_sp_ghep_doc);\r\n       \r\nreturn tong;\r\n}','','[\"11\"]',36,'1677226097','1677228045'),(66,0,'Tính tiền in tờ rớt nếu có','tinh_tien_in_to_rot(so_luong_to_cap)','function tinh_tien_in_to_rot(so_luong_to_cap)\r\n{\r\n    var tien_in_to_rot=0;\r\n    var so_to_rot =so_luong_to_cap- <so_luong_to_cap_toi_da>;\r\n    tien_in_to_rot =so_to_rot*<phi_in_to_rot>;\r\n    if(tien_in_to_rot>0) return tien_in_to_rot;\r\n    else return 0;\r\n   \r\n   \r\n}','[\"994\",\"995\"]','',35,'1677295110','1677295850'),(67,0,'Tính số sản phẩm trên tờ','tinh_so_sp_tren_kho(rong,dai,rong_kho_giay,dai_kho_giay)','function tinh_so_sp_tren_kho(rong,dai,rong_kho_giay,dai_kho_giay){\r\n      \r\n     var kho_trai_cao=0;//=tinh_kho_trai_cao(cao, rong, kieu_hop);\r\n     var kho_trai_ngang=0;//=tinh_kho_trai_ngang(dai,rong, kieu_hop);\r\n     \r\n     // tem \r\n     \r\n          kho_trai_cao=rong+0.3;\r\n          kho_trai_ngang=dai+0.3;\r\n      \r\n             dai_kho_giay =dai_kho_giay;\r\n             rong_kho_giay=rong_kho_giay;\r\n             \r\n      // ghép ngang     \r\n          so_sp_xep_ngang_ghep_ngang=Math.floor(dai_kho_giay/kho_trai_cao);\r\n         // return so_sp_xep_ngang;  \r\n          so_sp_xep_doc_ghep_ngang=Math.floor(rong_kho_giay/kho_trai_ngang);\r\n          \r\n          tong_sp_ghep_ngang=so_sp_xep_ngang_ghep_ngang*so_sp_xep_doc_ghep_ngang;\r\n          \r\n       // trường hợp ghép dọc\r\n   \r\n        so_sp_xep_ngang_ghep_doc=Math.floor(dai_kho_giay/kho_trai_ngang);\r\n         \r\n        so_sp_xep_doc_ghep_doc=Math.floor(rong_kho_giay/kho_trai_cao);\r\n        \r\n        tong_sp_ghep_doc=so_sp_xep_ngang_ghep_doc*so_sp_xep_doc_ghep_doc;\r\n        \r\n        var tong=0;\r\n        tong= MaxTwoNum(tong_sp_ghep_ngang,tong_sp_ghep_doc);\r\n    if(tong===0) tong =1;\r\n       return tong;\r\n      \r\n}   ','','[\"11\"]',9,'1698137462','1702077675');
