-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `pid` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `name` varchar(100) NOT NULL,
  `name_seo` varchar(200) NOT NULL,
  `link` varchar(500) NOT NULL,
  `keyword` varchar(200) NOT NULL,
  `image` varchar(100) NOT NULL,
  `img_path` varchar(1000) NOT NULL,
  `cid` int NOT NULL,
  `priceid` int NOT NULL,
  `eid` int NOT NULL,
  `brand_id` int NOT NULL,
  `vendor` varchar(50) NOT NULL,
  `time_warranty` varchar(50) NOT NULL,
  `related_product` varchar(100) NOT NULL,
  `enable` tinyint NOT NULL,
  `new` tinyint NOT NULL,
  `hot` tinyint NOT NULL,
  `hot_cate` int NOT NULL,
  `promo` tinyint NOT NULL,
  `combo` tinyint NOT NULL,
  `pos_index` int NOT NULL,
  `accept_voucher` tinyint NOT NULL,
  `original_price` int NOT NULL,
  `price` int NOT NULL,
  `short_desc` varchar(500) NOT NULL,
  `mota` text NOT NULL,
  `desc_html` text NOT NULL,
  `size` varchar(300) NOT NULL,
  `color` varchar(300) NOT NULL,
  `status` tinyint NOT NULL,
  `quantity` int NOT NULL,
  `gtin_code` varchar(100) NOT NULL,
  `mpn_code` varchar(100) NOT NULL,
  `created_at` varchar(50) DEFAULT NULL,
  `updated_at` varchar(50) DEFAULT NULL,
  `image_alt` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`pid`)
) ENGINE=InnoDB AUTO_INCREMENT=1737 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

